import {
  CONFIG,
  GYRO_TYPES,
  SIDE_COLORS,
  clamp,
  getAimDirection,
  getLaunchPower,
  getSpawnDistance,
  getSpinnerRadius,
  randomBetween,
  tierLabel,
  type GameMode,
  type GyroType,
} from './data';
import { AudioEngine } from './audio';
import { ParticleSystem } from './particles';
import {
  checkStopped,
  launchSpinner,
  resolveBoundary,
  resolveCollision,
  stepMovement,
  updateSpin,
  type BoundaryEvent,
  type CollisionEvent,
  type MoveInput,
} from './physics';
import { Spinner, drawGyro } from './spinner';
import {
  UI,
  type BattleView,
  type FighterHudView,
  type ResultView,
  type SelectionView,
} from './ui';

type ScreenState = 'menu' | 'select' | 'battle' | 'result';
/**
 * 严格时序：
 * intro（空场校准）→ entry（飞入落地）→ ready（等待发射）→ countdown（3·2·1 蓄力瞄准）→ fight → ending
 */
type BattlePhase = 'intro' | 'entry' | 'ready' | 'countdown' | 'fight' | 'ending';

interface SelectionState {
  mode: GameMode;
  p1Index: number;
  p2Index: number;
  active: 1 | 2;
  p1Locked: boolean;
  p2Locked: boolean;
  cpuThinking: boolean;
  /** 从结算页进入的“更换陀螺”流程：记录正在更换的一方。 */
  swapSide?: 1 | 2;
}

interface AiState {
  targetCharge: number;
  startDelay: number;
  aimBias: number;
  aimPhase: number;
  wobbleSpeed: number;
  steerPhase: number;
  /** CPU 冲刺节奏 */
  dashTimer: number;
  dashHold: number;
}

interface Dust {
  x: number;
  y: number;
  size: number;
  phase: number;
  speed: number;
}

interface Shockwave {
  x: number;
  y: number;
  radius: number;
  life: number;
  maxLife: number;
  color: string;
}

/** 开局入场：从屏幕外切入出生点的一条二次贝塞尔轨迹。 */
interface EntryFlight {
  side: 1 | 2;
  elapsed: number;
  delay: number;
  duration: number;
  fromX: number;
  fromY: number;
  controlX: number;
  controlY: number;
  toX: number;
  toY: number;
  trailTimer: number;
  started: boolean;
  landed: boolean;
}

/** 碰撞瞬间的局部白光爆闪：以接触点为圆心的加色光团。 */
interface ImpactFlash {
  x: number;
  y: number;
  radius: number;
  life: number;
  maxLife: number;
  color: string;
}

/** 战场飘字：Q 弹放大 → 上浮 → 淡出。 */
interface FloatingText {
  text: string;
  sub: string;
  x: number;
  y: number;
  life: number;
  maxLife: number;
  tone: 'max' | 'counter';
  rise: number;
  size: number;
}

/** 战败陀螺解体后的金属碎片。 */
interface Shard {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  length: number;
  angle: number;
  spin: number;
  life: number;
  maxLife: number;
  color: string;
  edge: string;
}

const MOVEMENT_KEYS = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Space',
  'Numpad0',
]);

export class Game {
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D;
  private readonly ui: UI;
  private readonly audio = new AudioEngine();
  private readonly particles = new ParticleSystem();

  private state: ScreenState = 'menu';
  private mode: GameMode = 'cpu';
  private selection: SelectionState | null = null;
  private cpuTimer = 0;
  private readyTimer = 0;
  /** 入场准备计时：空场展示瞄准射线，随后开始飞入。 */
  private prepTimer = 0;
  /** CPU 模式下，等待发射阶段自动触发倒计时的剩余时间（秒）。 */
  private readyAiTimer = 0;
  private hitStop = 0;
  /** 顿帧期间保持的强震幅度（MAX 撞击固定 8px）。 */
  private hitStopShake = 0;
  /** HUD 顶部信息栏的极小状态提示；战场内不再显示任何文字弹窗。 */
  private notice = '';
  private noticeTone: 'neutral' | 'good' | 'warn' | 'danger' = 'neutral';
  private noticeTimer = 0;

  private p1: Spinner | null = null;
  private p2: Spinner | null = null;
  private types: [GyroType, GyroType] = [GYRO_TYPES[0], GYRO_TYPES[0]];
  private battlePhase: BattlePhase = 'intro';
  private countdownTimer = 0;
  private goTimer = 0;
  /** 双方从屏幕外飞入出生点的入场轨迹；落地后置空。 */
  private entries: [EntryFlight, EntryFlight] | null = null;
  private entrySettleTimer = 0;
  private warmup = 0;
  private elapsed = 0;
  private resultTimer = 0;
  private collisionCooldown = 0;
  private wallCooldown = 0;
  private lastCountdownNumber = 0;
  private resultWinnerSide: 1 | 2 = 1;
  private resultDraw = false;
  private resultReason = '';
  private shatteredSide: 1 | 2 | null = null;
  private eliminationGrace = 0;
  private timeWarned = false;
  /** 从结算页点“更换陀螺”进入选人界面时置位，锁定后直接回到结算页。 */
  private returnToResult = false;
  private shake = 0;
  private ai: AiState = {
    targetCharge: 0.75,
    startDelay: 0,
    aimBias: 0,
    aimPhase: 0,
    wobbleSpeed: 1,
    steerPhase: 0,
    dashTimer: 2,
    dashHold: 0,
  };

  private width = 0;
  private height = 0;
  private dpr = 1;
  private centerX = 0;
  private centerY = 0;
  private arenaRadius = 300;
  private spinnerRadius = 22;

  private keys = new Set<string>();
  private dust: Dust[] = [];
  private shockwaves: Shockwave[] = [];
  private impactFlashes: ImpactFlash[] = [];
  private floatingTexts: FloatingText[] = [];
  /** MAX 撞击的整屏白光强度；顿帧期间不衰减，保持定格冲击。 */
  private screenFlash = 0;
  private shards: Shard[] = [];
  private screenTime = 0;
  private lastTime = 0;
  private accumulator = 0;
  private hudTimer = 0;
  private audioReady = false;

  constructor(canvas: HTMLCanvasElement, uiRoot: HTMLElement, utility: HTMLElement) {
    this.canvas = canvas;
    const context = canvas.getContext('2d', { alpha: true });
    if (!context) throw new Error('Canvas 2D context unavailable');
    this.ctx = context;
    this.ui = new UI(uiRoot, utility, {
      onMode: (mode) => this.enterSelect(mode),
      onBackToMenu: () => this.backToMenu(),
      onCard: (index) => this.chooseCard(index),
      onConfirm: () => this.confirmSelection(),
      onRematch: () => this.rematch(),
      onSwap: (side) => this.enterSwap(side),
      onToggleSfx: () => this.toggleSfx(),
      onToggleMusic: () => this.toggleMusic(),
    });

    this.createDust();
    this.resize();
    this.bindEvents();
    this.ui.showMenu();
    this.lastTime = performance.now();
    requestAnimationFrame(this.frame);
  }

  private bindEvents(): void {
    window.addEventListener('resize', this.handleResize);
    window.addEventListener('keydown', this.handleKeyDown, { passive: false });
    window.addEventListener('keyup', this.handleKeyUp);
    window.addEventListener('blur', this.handleBlur);
    document.addEventListener('visibilitychange', this.handleVisibility);
  }

  private ensureAudio(): void {
    if (this.audioReady) return;
    this.audioReady = true;
    void this.audio.unlock();
  }

  private handleResize = (): void => {
    this.resize();
  };

  private handleBlur = (): void => {
    this.keys.clear();
  };

  private handleVisibility = (): void => {
    if (document.hidden) {
      this.keys.clear();
      this.lastTime = performance.now();
    }
  };

  private handleKeyDown = (event: KeyboardEvent): void => {
    this.ensureAudio();
    if (event.code === 'Escape') {
      if (this.ui.helpOpen) {
        this.ui.closeHelp();
        event.preventDefault();
        return;
      }
      if (this.state === 'select' || this.state === 'result') {
        this.handleBack();
        event.preventDefault();
        return;
      }
    }

    if (this.ui.helpOpen) return;

    if (this.state === 'menu') {
      if (event.code === 'Digit1' || event.code === 'Numpad1') {
        this.enterSelect('cpu');
        event.preventDefault();
        return;
      }
      if (event.code === 'Digit2' || event.code === 'Numpad2') {
        this.enterSelect('pvp');
        event.preventDefault();
        return;
      }
      if (event.code === 'KeyH') {
        this.ui.openHelp();
        event.preventDefault();
        return;
      }
      return;
    }

    if (this.state === 'select') {
      if (MOVEMENT_KEYS.has(event.code)) event.preventDefault();
      if (event.repeat) return;
      this.handleSelectKey(event.code);
      return;
    }

    if (this.state === 'result') {
      if (event.code === 'Enter' || event.code === 'NumpadEnter') {
        this.rematch();
        event.preventDefault();
        return;
      }
      if (event.code === 'Digit1' || event.code === 'Numpad1') {
        this.enterSwap(1);
        event.preventDefault();
        return;
      }
      if (event.code === 'Digit2' || event.code === 'Numpad2') {
        this.enterSwap(2);
        event.preventDefault();
        return;
      }
      if (event.code === 'KeyH') {
        this.ui.openHelp();
        event.preventDefault();
      }
      return;
    }

    if (this.state === 'battle') {
      if (MOVEMENT_KEYS.has(event.code)) event.preventDefault();
      // 等待发射阶段只接受一次全新的按下，避免入场前按住的键直接触发倒计时。
      if (
        this.battlePhase === 'ready' &&
        event.repeat &&
        (event.code === 'Space' || event.code === 'Numpad0')
      ) {
        return;
      }
      this.keys.add(event.code);
    }
  };

  private handleKeyUp = (event: KeyboardEvent): void => {
    this.keys.delete(event.code);
  };

  private handleSelectKey(code: string): void {
    const selection = this.selection;
    if (!selection || selection.p1Locked && selection.p2Locked) return;

    if (code === 'KeyH') {
      this.ui.openHelp();
      return;
    }

    if (selection.active === 1 && !selection.p1Locked) {
      if (code === 'KeyA') this.moveSelection(-1);
      else if (code === 'KeyD') this.moveSelection(1);
      else if (code === 'Space') this.confirmSelection();
      return;
    }

    if (
      (selection.mode === 'pvp' || selection.swapSide === 2) &&
      selection.active === 2 &&
      !selection.p2Locked
    ) {
      if (code === 'ArrowLeft') this.moveSelection(-1);
      else if (code === 'ArrowRight') this.moveSelection(1);
      else if (code === 'Numpad0') this.confirmSelection();
    }
  }

  private enterSelect(mode: GameMode): void {
    this.ensureAudio();
    this.audio.playConfirm();
    this.mode = mode;
    this.returnToResult = false;
    this.state = 'select';
    this.selection = {
      mode,
      p1Index: 0,
      p2Index: 1,
      active: 1,
      p1Locked: false,
      p2Locked: false,
      cpuThinking: false,
    };
    this.cpuTimer = 0;
    this.readyTimer = 0;
    this.keys.clear();
    this.ui.showSelect(this.selectionView());
  }

  private selectionView(): SelectionView {
    if (!this.selection) {
      return {
        mode: this.mode,
        p1Index: 0,
        p2Index: 1,
        active: 1,
        p1Locked: false,
        p2Locked: false,
        cpuThinking: false,
      };
    }
    return { ...this.selection };
  }

  private moveSelection(direction: number): void {
    const selection = this.selection;
    if (!selection) return;
    if (selection.active === 1) {
      selection.p1Index =
        (selection.p1Index + direction + GYRO_TYPES.length) % GYRO_TYPES.length;
    } else {
      selection.p2Index =
        (selection.p2Index + direction + GYRO_TYPES.length) % GYRO_TYPES.length;
    }
    this.audio.playSelect();
    this.ui.updateSelect(this.selectionView());
  }

  private chooseCard(index: number): void {
    const selection = this.selection;
    if (!selection || index < 0 || index >= GYRO_TYPES.length) return;
    if (selection.active === 1 && !selection.p1Locked) {
      selection.p1Index = index;
    } else if (
      selection.active === 2 &&
      (selection.mode === 'pvp' || selection.swapSide === 2) &&
      !selection.p2Locked
    ) {
      selection.p2Index = index;
    } else {
      return;
    }
    this.audio.playSelect();
    this.ui.updateSelect(this.selectionView());
  }

  private confirmSelection(): void {
    const selection = this.selection;
    if (!selection) return;

    if (selection.active === 1 && !selection.p1Locked) {
      selection.p1Locked = true;
      selection.active = 2;
      this.audio.playConfirm();
      // 更换流程里不再让 AI 介入：CPU 的机体由玩家临时接管。
      if (selection.mode === 'cpu' && !this.returnToResult) {
        selection.cpuThinking = true;
        this.cpuTimer = randomBetween(0.62, 0.95);
      }
      this.armReadyTimer();
      this.ui.updateSelect(this.selectionView());
      return;
    }

    if (
      (selection.mode === 'pvp' || selection.swapSide === 2) &&
      selection.active === 2 &&
      !selection.p2Locked
    ) {
      selection.p2Locked = true;
      this.audio.playConfirm();
      this.armReadyTimer();
      this.ui.updateSelect(this.selectionView());
    }
  }

  /** 双方都锁定后才启动“进入圆桌 / 返回结算”的缓冲计时。 */
  private armReadyTimer(): void {
    const selection = this.selection;
    if (!selection || !selection.p1Locked || !selection.p2Locked) return;
    if (this.returnToResult) this.readyTimer = 0.5;
    else if (selection.mode === 'pvp') this.readyTimer = 0.85;
  }

  private completeCpuChoice(): void {
    const selection = this.selection;
    if (!selection) return;
    selection.cpuThinking = false;
    selection.p2Index = Math.floor(Math.random() * GYRO_TYPES.length);
    selection.p2Locked = true;
    this.audio.playConfirm();
    this.readyTimer = 0.85;
    this.ui.updateSelect(this.selectionView());
  }

  private updateSelection(dt: number): void {
    const selection = this.selection;
    if (!selection || this.ui.helpOpen) return;
    if (selection.cpuThinking) {
      this.cpuTimer -= dt;
      if (this.cpuTimer <= 0) this.completeCpuChoice();
    }
    if (selection.p1Locked && selection.p2Locked && this.readyTimer > 0) {
      this.readyTimer -= dt;
      if (this.readyTimer <= 0) {
        if (this.returnToResult) this.finishSwap();
        else this.beginBattle();
      }
    }
  }

  private beginBattle(): void {
    const selection = this.selection;
    if (!selection) return;
    this.mode = selection.mode;
    this.types = [GYRO_TYPES[selection.p1Index], GYRO_TYPES[selection.p2Index]];
    this.setupBattle();
  }

  private setupBattle(): void {
    this.state = 'battle';
    // 先进入空场准备：不显示机体与瞄准箭头，只保留 HUD。
    this.battlePhase = 'intro';
    this.countdownTimer = CONFIG.countdown.duration;
    this.goTimer = 0;
    this.warmup = 0;
    this.elapsed = 0;
    this.resultTimer = 0;
    this.collisionCooldown = 0;
    this.wallCooldown = 0;
    this.lastCountdownNumber = 0;
    this.resultDraw = false;
    this.resultReason = '';
    this.shatteredSide = null;
    this.eliminationGrace = 0;
    this.timeWarned = false;
    this.shake = 0;
    this.hitStop = 0;
    this.hitStopShake = 0;
    this.notice = '';
    this.noticeTimer = 0;
    this.entries = null;
    this.entrySettleTimer = 0;
    // 空场校准约 0.75 秒，之后自动进入飞入落地。
    this.prepTimer = 0.75;
    this.keys.clear();
    this.particles.clear();
    this.shockwaves = [];
    this.impactFlashes = [];
    this.floatingTexts = [];
    this.screenFlash = 0;
    this.shards = [];
    this.ui.closeHelp();

    const spawn = getSpawnDistance(this.arenaRadius);
    this.spinnerRadius = getSpinnerRadius(this.arenaRadius);
    this.p1 = new Spinner({
      side: 1,
      type: this.types[0],
      x: -spawn,
      y: 0,
      radius: this.spinnerRadius * this.types[0].radiusScale,
    });
    this.p2 = new Spinner({
      side: 2,
      type: this.types[1],
      x: spawn,
      y: 0,
      radius: this.spinnerRadius * this.types[1].radiusScale,
    });
    this.p1.pos.x = -spawn;
    this.p2.pos.x = spawn;
    this.p1.aimOffset = 0;
    this.p2.aimOffset = 0;
    this.configureAi();

    this.ui.showBattle(this.mode, this.types[0], this.types[1]);
    this.refreshBattleUI();
  }

  private configureAi(): void {
    const roll = Math.random();
    let target: number;
    if (roll < CONFIG.ai.redChance) {
      target = randomBetween(CONFIG.ai.redMin, CONFIG.ai.redMax);
    } else if (roll < CONFIG.ai.redChance + CONFIG.ai.maxChance) {
      target = 1;
    } else {
      target = randomBetween(CONFIG.ai.underMin, CONFIG.ai.underMax);
    }
    this.ai = {
      targetCharge: target,
      startDelay: randomBetween(CONFIG.ai.startDelayMin, CONFIG.ai.startDelayMax),
      aimBias: randomBetween(-CONFIG.ai.aimBiasMax, CONFIG.ai.aimBiasMax),
      aimPhase: Math.random() * Math.PI * 2,
      wobbleSpeed: randomBetween(1.2, 2.3),
      steerPhase: Math.random() * Math.PI * 2,
      dashTimer: randomBetween(CONFIG.dash.aiFirstDelayMin, CONFIG.dash.aiFirstDelayMax),
      dashHold: 0,
    };
  }

  private rematch(): void {
    this.ensureAudio();
    if (!this.types[0] || !this.types[1]) return;
    this.returnToResult = false;
    this.setupBattle();
  }

  /** 结算页“更换陀螺”：只重开选人界面，锁定后回到结算页。 */
  private enterSwap(side: 1 | 2): void {
    this.ensureAudio();
    if (this.state !== 'result') return;
    this.audio.playConfirm();
    this.returnToResult = true;
    this.readyTimer = 0;
    this.cpuTimer = 0;
    this.state = 'select';
    this.selection = {
      mode: this.mode,
      p1Index: Math.max(0, GYRO_TYPES.indexOf(this.types[0])),
      p2Index: Math.max(0, GYRO_TYPES.indexOf(this.types[1])),
      active: side,
      p1Locked: side !== 1,
      p2Locked: side !== 2,
      cpuThinking: false,
      swapSide: side,
    };
    this.keys.clear();
    this.ui.showSelect(this.selectionView());
  }

  /** 更换完成后带着新机体直接回到结算页，不重开对局。 */
  private finishSwap(): void {
    const selection = this.selection;
    if (!selection) return;
    this.readyTimer = 0;
    this.cpuTimer = 0;
    this.types = [GYRO_TYPES[selection.p1Index], GYRO_TYPES[selection.p2Index]];
    this.returnToResult = false;
    this.selection = null;
    this.particles.clear();
    this.shockwaves = [];
    this.impactFlashes = [];
    this.floatingTexts = [];
    this.screenFlash = 0;
    this.shards = [];
    this.audio.playConfirm();
    this.showResult(false);
  }

  private handleBack(): void {
    if (this.returnToResult) {
      this.finishSwap();
      return;
    }
    this.backToMenu();
  }

  private backToMenu(): void {
    this.state = 'menu';
    this.selection = null;
    this.p1 = null;
    this.p2 = null;
    this.returnToResult = false;
    this.resultDraw = false;
    this.shatteredSide = null;
    this.entries = null;
    this.hitStop = 0;
    this.hitStopShake = 0;
    this.notice = '';
    this.noticeTimer = 0;
    this.particles.clear();
    this.shockwaves = [];
    this.impactFlashes = [];
    this.floatingTexts = [];
    this.screenFlash = 0;
    this.shards = [];
    this.shake = 0;
    this.keys.clear();
    this.audio.playSelect();
    this.ui.showMenu();
  }

  private toggleSfx(): void {
    this.ensureAudio();
    const enabled = !this.audio.sfxEnabled;
    this.audio.setSfxEnabled(enabled);
    this.ui.setAudioState(enabled, this.audio.musicEnabled);
    if (enabled) this.audio.playSelect();
  }

  private toggleMusic(): void {
    this.ensureAudio();
    const enabled = !this.audio.musicEnabled;
    this.audio.setMusicEnabled(enabled);
    this.ui.setAudioState(this.audio.sfxEnabled, enabled);
  }

  private handleAimInput(): void {
    if (!this.p1 || !this.p2) return;
    const p1Up = this.keys.has('KeyW');
    const p1Down = this.keys.has('KeyS');
    const p1Direction = p1Down === p1Up ? 0 : p1Down ? 1 : -1;
    this.p1.updateAim(p1Direction as -1 | 0 | 1, CONFIG.timestep);

    if (this.mode === 'pvp') {
      const p2Up = this.keys.has('ArrowUp');
      const p2Down = this.keys.has('ArrowDown');
      const p2Direction = p2Down === p2Up ? 0 : p2Down ? 1 : -1;
      this.p2.updateAim(p2Direction as -1 | 0 | 1, CONFIG.timestep);
    }
  }

  private updateAiAim(dt: number): void {
    if (!this.p2) return;
    const wobble =
      Math.sin(this.screenTime * this.ai.wobbleSpeed + this.ai.aimPhase) *
      CONFIG.ai.wobble;
    const targetAim = clamp(
      this.ai.aimBias + wobble,
      -CONFIG.aim.limit * 0.92,
      CONFIG.aim.limit * 0.92,
    );
    this.p2.aimOffset +=
      (targetAim - this.p2.aimOffset) *
      Math.min(1, dt * CONFIG.aim.aiLerp);
  }

  private updateAiCountdown(dt: number): void {
    if (!this.p2) return;
    if (this.ai.startDelay > 0) {
      this.ai.startDelay -= dt;
      this.p2.updateCharge(false, dt);
    } else {
      const holding =
        this.ai.targetCharge >= 0.995
          ? true
          : this.p2.charge < this.ai.targetCharge;
      this.p2.updateCharge(holding, dt);
    }
    this.updateAiAim(dt);
  }

  /** 入场准备：场地空无一物，只保留 HUD，不接受任何操作。 */
  private tickIntro(dt: number): void {
    if (!this.p1 || !this.p2) return;
    this.prepTimer -= dt;
    if (this.prepTimer <= 0) this.beginEntry();
  }

  /** 开始飞入：这一刻才把双方移到屏幕外，之前绝不显示机体。 */
  private beginEntry(): void {
    if (!this.p1 || !this.p2) return;
    this.battlePhase = 'entry';
    this.entries = null;
    this.entrySettleTimer = 0;
    this.startEntryFlights();
    this.setNotice('双方机体入场 · 落地后开始倒计时', 'neutral', 1500);
    this.refreshBattleUI();
  }

  private tickCountdown(dt: number): void {
    if (!this.p1 || !this.p2) return;
    this.countdownTimer -= dt;
    this.handleAimInput();
    this.p1.updateCharge(this.keys.has('Space'), dt);
    if (this.mode === 'cpu') {
      this.updateAiCountdown(dt);
    } else {
      this.p2.updateCharge(this.keys.has('Numpad0'), dt);
    }

    const number = Math.max(
      1,
      Math.min(3, Math.ceil(this.countdownTimer - 0.22)),
    );
    if (number !== this.lastCountdownNumber) {
      this.lastCountdownNumber = number;
      this.audio.playCountdown(number === 1);
    }

    // 倒计时归零的瞬间才执行发射：按当前蓄力与瞄准角给双方初速度。
    if (this.countdownTimer <= 0) this.startFight();
  }

  /** 生成两条从屏幕外切入出生点的抛物线轨迹。 */
  private startEntryFlights(): void {
    if (!this.p1 || !this.p2) return;
    const spawn = getSpawnDistance(this.arenaRadius);
    const reach = this.centerX + Math.max(this.p1.radius, this.p2.radius) * 2.4;
    const arc = this.arenaRadius * 0.3;

    this.p1.pos.x = -reach;
    this.p1.pos.y = -arc * 0.55;
    this.p1.vel.x = 0;
    this.p1.vel.y = 0;
    this.p2.pos.x = reach;
    this.p2.pos.y = arc * 0.55;
    this.p2.vel.x = 0;
    this.p2.vel.y = 0;

    this.entries = [
      {
        side: 1,
        elapsed: 0,
        delay: 0,
        duration: 0.66,
        fromX: -reach,
        fromY: -arc * 0.55,
        controlX: -spawn * 1.55,
        controlY: -arc,
        toX: -spawn,
        toY: 0,
        trailTimer: 0,
        started: false,
        landed: false,
      },
      {
        side: 2,
        elapsed: 0,
        delay: 0.12,
        duration: 0.66,
        fromX: reach,
        fromY: arc * 0.55,
        controlX: spawn * 1.55,
        controlY: arc,
        toX: spawn,
        toY: 0,
        trailTimer: 0,
        started: false,
        landed: false,
      },
    ];
    // 落地冲击波扩散一小段时间后再进入等待发射，避免两个仪式重叠。
    this.entrySettleTimer = 0.32;
  }

  /** 入场飞行：只更新视觉位置与拖尾，不参与任何物理判定。 */
  private tickEntry(dt: number): void {
    if (!this.p1 || !this.p2 || !this.entries) {
      this.beginReady();
      return;
    }

    for (const entry of this.entries) {
      if (entry.landed) continue;
      const spinner = entry.side === 1 ? this.p1 : this.p2;
      entry.elapsed += dt;
      const local = entry.elapsed - entry.delay;
      if (local <= 0) continue;

      if (!entry.started) {
        entry.started = true;
        this.audio.playLaunchWhoosh(entry.side);
      }

      const prevX = spinner.pos.x;
      const prevY = spinner.pos.y;
      const t = clamp(local / entry.duration, 0, 1);
      // 强减速曲线：高速切入，最后稳稳压在出生点上。
      const eased = 1 - Math.pow(1 - t, 3);
      const inv = 1 - eased;
      const x =
        inv * inv * entry.fromX +
        2 * inv * eased * entry.controlX +
        eased * eased * entry.toX;
      const y =
        inv * inv * entry.fromY +
        2 * inv * eased * entry.controlY +
        eased * eased * entry.toY;

      spinner.pos.x = x;
      spinner.pos.y = y;
      if (dt > 0) {
        spinner.vel.x = (x - prevX) / dt;
        spinner.vel.y = (y - prevY) / dt;
      }

      entry.trailTimer -= dt;
      if (entry.trailTimer <= 0 && t < 0.985) {
        entry.trailTimer = 0.014;
        this.spawnEntryTrail(spinner);
      }

      if (t >= 1) this.landEntry(entry, spinner);
    }

    if (this.entries.every((entry) => entry.landed)) {
      this.entrySettleTimer -= dt;
      if (this.entrySettleTimer <= 0) this.beginReady();
    }
  }

  private spawnEntryTrail(spinner: Spinner): void {
    const speed = Math.hypot(spinner.vel.x, spinner.vel.y) || 1;
    const angle = Math.atan2(spinner.vel.y, spinner.vel.x) + Math.PI;
    this.particles.burst(
      spinner.pos.x - (spinner.vel.x / speed) * spinner.radius * 0.85,
      spinner.pos.y - (spinner.vel.y / speed) * spinner.radius * 0.85,
      {
        count: 2,
        color: spinner.type.colors.accent,
        speedMin: this.arenaRadius * 0.04,
        speedMax: this.arenaRadius * 0.26,
        sizeMin: 1,
        sizeMax: 2.6,
        lifeMin: 0.12,
        lifeMax: 0.3,
        direction: angle,
        spread: 0.55,
      },
    );
  }

  /** 落地：圆环冲击波 + 灰尘粒子 + 轻微震动。 */
  private landEntry(entry: EntryFlight, spinner: Spinner): void {
    if (entry.landed) return;
    entry.landed = true;
    spinner.pos.x = entry.toX;
    spinner.pos.y = entry.toY;
    spinner.vel.x = 0;
    spinner.vel.y = 0;
    spinner.hitFlash = Math.max(spinner.hitFlash, 0.4);

    const color = SIDE_COLORS[entry.side].main;
    this.audio.playEntryLanding(getLaunchPower(spinner.charge));
    this.addShockwave(entry.toX, entry.toY, spinner.radius * 0.62, color, 0.55);
    this.addShockwave(
      entry.toX,
      entry.toY,
      spinner.radius * 1.08,
      'rgba(255, 246, 224, 0.9)',
      0.42,
    );
    this.particles.burst(entry.toX, entry.toY, {
      count: 16,
      color,
      speedMin: this.arenaRadius * 0.12,
      speedMax: this.arenaRadius * 0.5,
      sizeMin: 1,
      sizeMax: 3,
      lifeMin: 0.18,
      lifeMax: 0.5,
    });
    this.particles.burst(entry.toX, entry.toY, {
      count: 8,
      color: '#fff6e4',
      speedMin: 0,
      speedMax: this.arenaRadius * 0.14,
      sizeMin: 2,
      sizeMax: 5,
      lifeMin: 0.08,
      lifeMax: 0.18,
      kind: 'dot',
    });
    this.shake = Math.max(this.shake, 2.2);
  }

  /** 落地稳定后进入等待发射阶段，不自动开始倒计时。 */
  private beginReady(): void {
    if (!this.p1 || !this.p2) return;
    this.entries = null;
    this.entrySettleTimer = 0;
    this.battlePhase = 'ready';
    this.countdownTimer = CONFIG.countdown.duration;
    this.lastCountdownNumber = 0;
    this.goTimer = 0;
    this.warmup = 0;
    this.elapsed = 0;
    this.collisionCooldown = 0;
    this.readyAiTimer =
      this.mode === 'cpu'
        ? randomBetween(CONFIG.ai.readyDelayMin, CONFIG.ai.readyDelayMax)
        : 0;
    // 入场前按住的发射键不算数，必须重新按一次才开始倒计时。
    this.keys.delete('Space');
    this.keys.delete('Numpad0');

    const spawn = getSpawnDistance(this.arenaRadius);
    for (const spinner of [this.p1, this.p2]) {
      const dir = spinner.side === 1 ? -1 : 1;
      spinner.pos.x = dir * spawn;
      spinner.pos.y = 0;
      spinner.vel.x = 0;
      spinner.vel.y = 0;
      spinner.launched = false;
      spinner.hitFlash = 0;
      spinner.aimOffset = 0;
      spinner.aimVelocity = 0;
      spinner.resetCharge();
    }
    this.setNotice('等待发射 · 任意一方按下发射键开始倒计时', 'neutral', 1800);
    this.refreshBattleUI();
  }

  /**
   * 双方确认发射后进入 3·2·1。
   * 倒计时期间双方被钉在出生点，只允许蓄力与调整瞄准。
   * 保留等待阶段已经调整好的瞄准角。
   */
  private beginChargingCountdown(): void {
    if (!this.p1 || !this.p2) return;
    this.entries = null;
    this.entrySettleTimer = 0;
    this.battlePhase = 'countdown';
    this.countdownTimer = CONFIG.countdown.duration;
    this.lastCountdownNumber = 0;
    this.goTimer = 0;
    this.warmup = 0;
    this.elapsed = 0;
    this.collisionCooldown = 0;

    const spawn = getSpawnDistance(this.arenaRadius);
    for (const spinner of [this.p1, this.p2]) {
      const dir = spinner.side === 1 ? -1 : 1;
      spinner.pos.x = dir * spawn;
      spinner.pos.y = 0;
      spinner.vel.x = 0;
      spinner.vel.y = 0;
      spinner.launched = false;
      spinner.hitFlash = 0;
      spinner.resetCharge();
    }
    if (this.mode === 'cpu') {
      this.ai.startDelay = randomBetween(
        CONFIG.ai.startDelayMin,
        CONFIG.ai.startDelayMax,
      );
    }
    this.setNotice('3 · 2 · 1 · 按住蓄力并调整瞄准', 'neutral', 1600);
    this.refreshBattleUI();
  }

  /**
   * 等待发射：机体停在出生点，可先调整瞄准。
   * PvP：P1 按 SPACE / P2 按小键盘 0 才进入 3 秒倒计时。
   * CPU：玩家按 SPACE 可提前开始；不按则由 AI 在准备完成后自动触发。
   */
  private tickReady(dt: number): void {
    if (!this.p1 || !this.p2) return;
    this.handleAimInput();
    if (this.mode === 'cpu') {
      this.updateAiAim(dt);
      this.readyAiTimer -= dt;
      // 玩家可以先按 SPACE 开始；不按则由 AI 在短暂准备后自动触发。
      if (this.readyAiTimer <= 0 || this.keys.has('Space')) {
        this.beginChargingCountdown();
      }
      return;
    }
    if (this.keys.has('Space') || this.keys.has('Numpad0')) {
      this.beginChargingCountdown();
    }
  }

  /** 倒计时归零：按当前蓄力档位与瞄准角发射，正式开战。 */
  private startFight(): void {
    if (!this.p1 || !this.p2) return;
    this.entries = null;
    this.entrySettleTimer = 0;
    launchSpinner(this.p1, this.arenaRadius);
    launchSpinner(this.p2, this.arenaRadius);
    // 发射键必须松开后重新按下，才算“再次蓄力”进入冲刺。
    this.p1.dashHeld = true;
    this.p2.dashHeld = true;
    this.battlePhase = 'fight';
    this.goTimer = CONFIG.countdown.goFlash;
    this.warmup = CONFIG.physics.warmupDuration;
    this.elapsed = 0;
    this.collisionCooldown = 0;

    const strongest = Math.max(
      getLaunchPower(this.p1.charge),
      getLaunchPower(this.p2.charge),
    );
    this.audio.playLaunch(strongest);
    this.audio.playGo();
    this.addShockwave(this.p1.pos.x, this.p1.pos.y, this.spinnerRadius * 1.2, this.p1.type.colors.accent, 0.5);
    this.addShockwave(this.p2.pos.x, this.p2.pos.y, this.spinnerRadius * 1.2, this.p2.type.colors.accent, 0.5);
    this.particles.burst(this.p1.pos.x, this.p1.pos.y, {
      count: 9,
      color: SIDE_COLORS[1].main,
      speedMin: this.arenaRadius * 0.18,
      speedMax: this.arenaRadius * 0.55,
      sizeMin: 1,
      sizeMax: 2.2,
      lifeMin: 0.2,
      lifeMax: 0.45,
      direction: Math.atan2(this.p1.vel.y, this.p1.vel.x) + Math.PI,
      spread: 0.65,
    });
    this.particles.burst(this.p2.pos.x, this.p2.pos.y, {
      count: 9,
      color: SIDE_COLORS[2].main,
      speedMin: this.arenaRadius * 0.18,
      speedMax: this.arenaRadius * 0.55,
      sizeMin: 1,
      sizeMax: 2.2,
      lifeMin: 0.2,
      lifeMax: 0.45,
      direction: Math.atan2(this.p2.vel.y, this.p2.vel.x) + Math.PI,
      spread: 0.65,
    });
    this.shake = Math.max(this.shake, 1.3);

    const launchTone = this.p1.tier === 'max' || this.p2.tier === 'max' ? 'warn' : 'neutral';
    this.setNotice(
      `P1 ${tierLabel(this.p1.tier)} · P2 ${tierLabel(this.p2.tier)} · 发射`,
      launchTone,
      1400,
    );
    this.refreshBattleUI();
  }

  private playerOneMove(): MoveInput {
    return {
      x: (this.keys.has('KeyD') ? 1 : 0) - (this.keys.has('KeyA') ? 1 : 0),
      y: (this.keys.has('KeyS') ? 1 : 0) - (this.keys.has('KeyW') ? 1 : 0),
    };
  }

  private playerTwoMove(): MoveInput {
    return {
      x: (this.keys.has('ArrowRight') ? 1 : 0) - (this.keys.has('ArrowLeft') ? 1 : 0),
      y: (this.keys.has('ArrowDown') ? 1 : 0) - (this.keys.has('ArrowUp') ? 1 : 0),
    };
  }

  /** 局内冲刺：按住蓄力，松开后朝对手方向突进。 */
  private updateDashInput(side: 1 | 2, holding: boolean, dt: number): void {
    const spinner = side === 1 ? this.p1 : this.p2;
    const opponent = side === 1 ? this.p2 : this.p1;
    if (!spinner || !opponent || !spinner.launched || spinner.out) return;

    spinner.dashCooldown = Math.max(0, spinner.dashCooldown - dt);
    spinner.dashLockout = Math.max(0, spinner.dashLockout - dt);
    if (spinner.dashActive > 0) {
      spinner.dashActive = Math.max(0, spinner.dashActive - dt);
      // 满力冲刺未命中：窗口结束后清空标记，避免它残留到下一次普通碰撞。
      if (spinner.dashActive === 0) spinner.dashWasMaxHit = false;
    }

    // 封锁期间强制中断蓄力；即使残留状态也绝不允许继续充能。
    if (spinner.dashLockout > 0 && spinner.dashCharging) {
      spinner.dashCharging = false;
      spinner.dashCharge = 0;
    }

    if (spinner.dashCharging) {
      if (!holding) {
        this.releaseDash(spinner, opponent);
      } else {
        spinner.dashCharge = Math.min(
          1,
          spinner.dashCharge + dt / CONFIG.dash.chargeDuration,
        );
      }
    } else if (
      holding &&
      !spinner.dashHeld &&
      spinner.dashCooldown <= 0 &&
      spinner.dashLockout <= 0 &&
      !spinner.dashInterrupted
    ) {
      spinner.dashCharging = true;
      spinner.dashCharge = 0;
    }

    if (!holding) spinner.dashInterrupted = false;
    spinner.dashHeld = holding;
  }

  private releaseDash(spinner: Spinner, opponent: Spinner): void {
    const power = Math.max(CONFIG.dash.minCharge, spinner.dashCharge);
    // 在松开瞬间冻结“是否满力冲刺”，命中后由碰撞逻辑消费，保证每次满力冲刺都能重新触发 MAX HIT。
    const maxCharge = spinner.dashCharge >= CONFIG.dash.maxChargeThreshold;
    const dx = opponent.pos.x - spinner.pos.x;
    const dy = opponent.pos.y - spinner.pos.y;
    const distance = Math.hypot(dx, dy) || 1;
    const dirX = dx / distance;
    const dirY = dy / distance;
    const speed = this.arenaRadius * (CONFIG.dash.speedBase + CONFIG.dash.speedGain * power);

    spinner.dashCharging = false;
    spinner.dashCharge = 0;
    spinner.dashPower = power;
    spinner.dashWasMaxHit = maxCharge;
    spinner.dashActive = CONFIG.dash.activeDuration;
    spinner.dashCooldown = CONFIG.dash.cooldown;
    spinner.dashInterrupted = false;
    spinner.vel.x = spinner.vel.x * 0.18 + dirX * speed;
    spinner.vel.y = spinner.vel.y * 0.18 + dirY * speed;
    spinner.hitFlash = Math.max(spinner.hitFlash, 0.35);

    this.audio.playDash(power);
    this.particles.burst(
      spinner.pos.x - dirX * spinner.radius * 0.8,
      spinner.pos.y - dirY * spinner.radius * 0.8,
      {
        count: 10 + Math.round(power * 10),
        color: SIDE_COLORS[spinner.side].main,
        speedMin: this.arenaRadius * 0.2,
        speedMax: this.arenaRadius * (0.55 + power * 0.55),
        sizeMin: 1,
        sizeMax: 2.8,
        lifeMin: 0.16,
        lifeMax: 0.42,
        direction: Math.atan2(-dirY, -dirX),
        spread: 0.85,
      },
    );
    this.addShockwave(
      spinner.pos.x,
      spinner.pos.y,
      spinner.radius * 0.8,
      SIDE_COLORS[spinner.side].main,
      0.3,
    );
  }

  /** CPU 也会择机蓄力冲刺，避免玩家单方面掌握新机制。 */
  private updateAiDash(dt: number): boolean {
    if (!this.p2) return false;
    // 被破招封锁时立刻松手，封锁结束后重新寻找冲刺时机。
    if (this.p2.dashLockout > 0) {
      this.ai.dashHold = 0;
      return false;
    }
    if (this.ai.dashHold > 0) {
      this.ai.dashHold -= dt;
      return true;
    }
    this.ai.dashTimer -= dt;
    if (this.ai.dashTimer <= 0 && this.p2.dashCooldown <= 0) {
      this.ai.dashHold = randomBetween(CONFIG.dash.aiHoldMin, CONFIG.dash.aiHoldMax);
      this.ai.dashTimer = randomBetween(CONFIG.dash.aiIntervalMin, CONFIG.dash.aiIntervalMax);
      return true;
    }
    return false;
  }

  private aiMove(): MoveInput {
    if (!this.p1 || !this.p2) return { x: 0, y: 0 };
    const me = this.p2;
    const opponent = this.p1;
    const dx = opponent.pos.x - me.pos.x;
    const dy = opponent.pos.y - me.pos.y;
    const distance = Math.hypot(dx, dy) || 1;
    const ownDistance = Math.hypot(me.pos.x, me.pos.y);
    const opponentDistance = Math.hypot(opponent.pos.x, opponent.pos.y);

    let x = 0;
    let y = 0;
    if (ownDistance > this.arenaRadius * CONFIG.ai.edgeCareRatio) {
      x = -me.pos.x / ownDistance;
      y = -me.pos.y / ownDistance;
    } else {
      const outX = opponentDistance > 1 ? opponent.pos.x / opponentDistance : 1;
      const outY = opponentDistance > 1 ? opponent.pos.y / opponentDistance : 0;
      const flankX = opponent.pos.x - outX * (me.radius + opponent.radius) * 0.9;
      const flankY = opponent.pos.y - outY * (me.radius + opponent.radius) * 0.9;
      x = flankX - me.pos.x;
      y = flankY - me.pos.y;
      const length = Math.hypot(x, y) || 1;
      x /= length;
      y /= length;

      if (distance < (me.radius + opponent.radius) * 2.5) {
        const side = Math.sin(this.screenTime * 1.35 + this.ai.steerPhase) * 0.5;
        x += (-dy / distance) * side;
        y += (dx / distance) * side;
      }
    }

    const jitterX = Math.sin(this.screenTime * 2.1 + this.ai.steerPhase) * CONFIG.ai.movementNoise;
    const jitterY = Math.cos(this.screenTime * 1.7 + this.ai.steerPhase * 1.8) * CONFIG.ai.movementNoise;
    x += jitterX;
    y += jitterY;
    const length = Math.hypot(x, y) || 1;
    return { x: x / length, y: y / length };
  }

  private tickFight(dt: number): void {
    if (!this.p1 || !this.p2) return;

    this.goTimer = Math.max(0, this.goTimer - dt);
    const wasWarmup = this.warmup > 0;
    this.warmup = Math.max(0, this.warmup - dt);
    if (wasWarmup && this.warmup === 0) {
      this.setNotice('LIVE · 热身结束，全功率碰撞', 'warn', 1400);
    }

    this.elapsed += dt;
    this.collisionCooldown = Math.max(0, this.collisionCooldown - dt);
    this.wallCooldown = Math.max(0, this.wallCooldown - dt);

    this.updateDashInput(1, this.keys.has('Space'), dt);
    if (this.mode === 'cpu') {
      this.updateDashInput(2, this.updateAiDash(dt), dt);
    } else {
      this.updateDashInput(2, this.keys.has('Numpad0'), dt);
    }
    this.updateMaxLightningSparks(dt);

    const p1Move = this.playerOneMove();
    const p2Move = this.mode === 'cpu' ? this.aiMove() : this.playerTwoMove();
    stepMovement(this.p1, p1Move, dt, this.arenaRadius);
    stepMovement(this.p2, p2Move, dt, this.arenaRadius);

    if (this.collisionCooldown <= 0) {
      const collision = resolveCollision(
        this.p1,
        this.p2,
        this.arenaRadius,
        this.warmup > 0,
      );
      if (collision) {
        this.collisionCooldown = CONFIG.physics.collisionCooldown;
        this.handleCollision(collision);
      }
    }

    const boundary1 = resolveBoundary(this.p1, this.arenaRadius);
    if (boundary1) this.handleBoundary(1, boundary1);
    const boundary2 = resolveBoundary(this.p2, this.arenaRadius);
    if (boundary2) this.handleBoundary(2, boundary2);

    updateSpin(this.p1, dt);
    updateSpin(this.p2, dt);
    this.spawnTrail(this.p1, dt);
    this.spawnTrail(this.p2, dt);

    checkStopped(this.p1);
    checkStopped(this.p2);

    const remaining = Math.max(0, CONFIG.match.timeLimit - this.elapsed);
    if (!this.timeWarned && remaining <= 10) {
      this.timeWarned = true;
      this.setNotice('剩余 10 秒 · 时间到按转速与位置判定', 'warn', 1600);
    }

    if (this.p1.out || this.p2.out) {
      // 出局后留一个极短宽限窗口，让“同一瞬间双方出局”能够成立。
      this.eliminationGrace += dt;
      if (this.p1.out && this.p2.out) {
        this.endMatch(null, this.doubleOutReason());
        return;
      }
      if (this.eliminationGrace >= CONFIG.match.doubleOutGrace) {
        const winner: 1 | 2 = this.p1.out ? 2 : 1;
        const loser = winner === 1 ? this.p2 : this.p1;
        this.endMatch(
          winner,
          loser.outReason === 'ring' ? '将对手击出圆桌' : '对手转速耗尽',
        );
      }
      return;
    }

    this.eliminationGrace = 0;

    if (remaining <= 0) this.resolveTimeLimit();
  }

  /** 时间到：只有判定帧的转速与坐标几乎完全一致才平局，否则必须分出胜负。 */
  private resolveTimeLimit(): void {
    if (!this.p1 || !this.p2) return;
    // 用百分比转速比较，避免不同机体血量上限造成的误判。
    const spinDiff = Math.abs(this.p1.spinRatio - this.p2.spinRatio);
    const posDiff = Math.hypot(
      this.p1.pos.x - this.p2.pos.x,
      this.p1.pos.y - this.p2.pos.y,
    );

    if (
      spinDiff <= CONFIG.match.tieSpinEpsilon &&
      posDiff <= CONFIG.match.tiePositionEpsilon
    ) {
      this.endMatch(null, '时间到 · 判定帧完全一致');
      return;
    }

    if (spinDiff > CONFIG.match.tieSpinEpsilon) {
      const winner: 1 | 2 = this.p1.spinRatio > this.p2.spinRatio ? 1 : 2;
      this.endMatch(winner, '时间到 · 对手转速更低');
      return;
    }

    const distance1 = Math.hypot(this.p1.pos.x, this.p1.pos.y);
    const distance2 = Math.hypot(this.p2.pos.x, this.p2.pos.y);
    if (Math.abs(distance1 - distance2) > CONFIG.match.tiePositionEpsilon) {
      this.endMatch(
        distance1 < distance2 ? 1 : 2,
        '时间到 · 更靠近桌心',
      );
      return;
    }

    // 转速与离桌心距离都一样，但坐标不同：仍视为不同判定帧，按坐标决出胜负。
    const winner: 1 | 2 =
      this.p1.pos.x !== this.p2.pos.x
        ? this.p1.pos.x < this.p2.pos.x
          ? 1
          : 2
        : this.p1.pos.y <= this.p2.pos.y
          ? 1
          : 2;
    this.endMatch(winner, '时间到 · 判定帧存在差异');
  }

  private doubleOutReason(): string {
    if (!this.p1 || !this.p2) return '双方同时出局';
    if (this.p1.outReason === 'ring' && this.p2.outReason === 'ring') {
      return '双方同时滑出圆桌';
    }
    if (this.p1.outReason === 'stop' && this.p2.outReason === 'stop') {
      return '双方转速同时归零';
    }
    return '双方在同一瞬间出局';
  }

  private tickEnding(dt: number): void {
    this.resultTimer -= dt;
    if (this.resultTimer <= 0) this.showResult();
  }

  private handleBoundary(side: 1 | 2, event: BoundaryEvent): void {
    const spinner = side === 1 ? this.p1 : this.p2;
    if (!spinner) return;

    if (event.kind === 'out') {
      this.particles.burst(spinner.pos.x, spinner.pos.y, {
        count: 16,
        color: '#fff3dc',
        speedMin: this.arenaRadius * 0.25,
        speedMax: this.arenaRadius * 0.95,
        sizeMin: 1,
        sizeMax: 3,
        lifeMin: 0.25,
        lifeMax: 0.7,
      });
      this.shake = Math.max(this.shake, CONFIG.camera.outShake);
      return;
    }

    if (event.speed > this.arenaRadius * 0.22 && this.wallCooldown <= 0) {
      this.wallCooldown = 0.075;
      const color = event.maxPenalty ? '#ff6651' : '#f0e2c4';
      this.particles.burst(spinner.pos.x, spinner.pos.y, {
        count: event.maxPenalty ? 15 : 8,
        color,
        speedMin: this.arenaRadius * 0.09,
        speedMax: this.arenaRadius * 0.46,
        sizeMin: 1,
        sizeMax: 2.5,
        lifeMin: 0.16,
        lifeMax: 0.48,
        direction: Math.atan2(event.normal.y, event.normal.x) + Math.PI,
        spread: 1.15,
      });
      this.audio.playWall(event.maxPenalty);
      this.shake = Math.max(
        this.shake,
        event.maxPenalty ? CONFIG.camera.heavyShake : CONFIG.camera.wallShake * 0.65,
      );
      if (event.maxPenalty) {
        this.addShockwave(spinner.pos.x, spinner.pos.y, this.spinnerRadius, '#ff6651', 0.7);
        this.setNotice(`P${side} MAX 撞墙 · 明显失速`, 'danger', 1800);
      }
    }
  }

  private handleCollision(event: CollisionEvent): void {
    if (!this.p1 || !this.p2) return;
    const intensity = clamp(event.impact / (this.arenaRadius * 2.1), 0, 1);
    const bonus = event.bonusA + event.bonusB;
    const dashImpact = event.dashA + event.dashB;
    const broken = event.brokenA || event.brokenB;
    // 只认发射瞬间冻结的 MAX 状态：即使首撞落在热身期、或碰撞时蓄力已被清空，
    // 也不会漏掉 MAX HIT。bonusA/B 只用于伤害结算，不再承担文字判定。
    const maxHit = event.maxA || event.maxB;
    const mainColor = event.warmup
      ? '#d8dfd3'
      : broken
        ? '#ff6d55'
        : dashImpact > 0
          ? '#ffe1a1'
          : bonus > 0
            ? '#ffb06f'
            : event.heavy
              ? '#ffd19a'
              : '#f3ead7';
    const count = clamp(
      12 +
        Math.round(intensity * 18) +
        (bonus > 0 ? 5 : 0) +
        Math.round(dashImpact * 12),
      CONFIG.particles.collisionMin,
      CONFIG.particles.collisionMax,
    );
    const angle = Math.atan2(event.normal.y, event.normal.x);
    this.particles.burst(event.point.x, event.point.y, {
      count,
      color: mainColor,
      speedMin: this.arenaRadius * 0.2,
      speedMax: this.arenaRadius * (0.75 + intensity * 0.9),
      sizeMin: 2,
      sizeMax: bonus > 0 ? 7 : 5.5,
      lifeMin: 0.2,
      lifeMax: 0.55,
      direction: angle,
      spread: Math.PI,
    });

    // 白热核心火花：更短命、更快，强化撞击瞬间的爆裂感。
    this.particles.burst(event.point.x, event.point.y, {
      count: clamp(8 + Math.round(intensity * 12), 8, 22),
      color: '#fffdf2',
      speedMin: this.arenaRadius * 0.4,
      speedMax: this.arenaRadius * (1.05 + intensity * 0.95),
      sizeMin: 1.4,
      sizeMax: 4.2,
      lifeMin: 0.1,
      lifeMax: 0.28,
      direction: angle,
      spread: Math.PI,
    });

    // 撞击闪光：极短命的大颗粒，模拟火花核心。
    this.particles.burst(event.point.x, event.point.y, {
      count: bonus > 0 ? 12 : 8,
      color: '#fff6dd',
      speedMin: 0,
      speedMax: this.arenaRadius * 0.16,
      sizeMin: 3.5,
      sizeMax: bonus > 0 ? 9 : 7,
      lifeMin: 0.05,
      lifeMax: 0.11,
      kind: 'dot',
      direction: angle,
      spread: Math.PI,
    });

    // 局部白光爆闪：普通重击保留一层，MAX 由 spawnMaxImpact 单独叠层。
    if (!event.warmup && !maxHit && (event.heavy || bonus > 0 || dashImpact > 0)) {
      this.addImpactFlash(
        event.point.x,
        event.point.y,
        this.spinnerRadius * 1.15,
        '#ffe7bc',
        0.12,
      );
    }

    const tier =
      event.bonusA > 0 ? this.p1.tier : event.bonusB > 0 ? this.p2.tier : 'under';
    this.audio.playHit(intensity, event.heavy || dashImpact > 0, tier);
    if (dashImpact > 0) this.audio.playDashImpact(dashImpact, intensity);
    // 碰撞后的分离摩擦：金属擦过桌面的短促刮擦声。
    this.audio.playScrape(intensity);

    if (event.heavy || bonus > 0 || dashImpact > 0) {
      this.addShockwave(
        event.point.x,
        event.point.y,
        this.spinnerRadius * (dashImpact > 0 ? 1.35 : 0.9),
        broken
          ? '#ff8067'
          : dashImpact > 0
            ? '#ffe3a3'
            : bonus > 0
              ? '#ffb271'
              : 'rgba(242, 229, 202, 0.8)',
        0.42 + intensity * 0.3,
      );
      this.shake = Math.max(
        this.shake,
        dashImpact > 0
          ? CONFIG.camera.heavyShake * 1.35
          : bonus > 0
            ? CONFIG.camera.heavyShake
            : CONFIG.camera.hitShake,
      );
    }

    // 破招飘字：只标注被撞断蓄力的那一方。
    // 它与 MAX HIT 是两个独立事件，不能用 else-if 互斥；同时触发时两行都要显示。
    if (!event.warmup) {
      const counterLift = this.spinnerRadius * (maxHit ? 3.5 : 2.7);
      if (event.brokenA) {
        this.addFloatingText(
          'COUNTER',
          '破招',
          this.p1.pos.x - this.spinnerRadius * 1.5,
          this.p1.pos.y - counterLift,
          'counter',
        );
      }
      if (event.brokenB) {
        this.addFloatingText(
          'COUNTER',
          '破招',
          this.p2.pos.x + this.spinnerRadius * 1.5,
          this.p2.pos.y - counterLift,
          'counter',
        );
      }
    }

    // MAX HIT 优先级最高：最后加入队列，绘制时压在 COUNTER 之上。
    // 发射时已经满力的首次有效撞击必须显示；热身期只补文字，不额外触发顿帧。
    if (maxHit) {
      if (event.warmup) {
        this.spawnMaxText();
      } else {
        this.triggerHitStop();
        this.spawnMaxImpact(event);
      }
    }

    if (!event.warmup) {
      // 状态提示仍写入顶部 HUD；战场内只保留碰撞飘字，不弹窗遮挡视野。
      if (maxHit) {
        this.setNotice(
          `MAX 命中 · ${event.maxA ? 'P1' : 'P2'} 造成额外转损`,
          'good',
          1200,
        );
      } else if (broken) {
        const brokenSide = event.brokenA ? 'P1' : 'P2';
        this.setNotice(`${brokenSide} 冲刺被打断 · 本次受伤加重`, 'danger', 1500);
      }
    }
  }

  /**
   * MAX 满力撞击的专属视觉包：接触点白光核心、三层扩散冲击波、
   * 整屏爆闪与金色 MAX HIT 飘字。全部由顿帧冻结在峰值，形成定格冲击。
   */
  private spawnMaxImpact(event: CollisionEvent): void {
    if (!this.p1 || !this.p2) return;
    const point = event.point;

    // 白光核心：三层同心爆闪，中心接近纯白但边缘快速收束，不糊成一团。
    this.addImpactFlash(point.x, point.y, this.spinnerRadius * 1.9, '#fffdf6', 0.2);
    this.addImpactFlash(point.x, point.y, this.spinnerRadius * 1.12, '#ffffff', 0.15);
    this.addImpactFlash(point.x, point.y, this.spinnerRadius * 0.6, '#fff2c8', 0.11);

    // 向外扩散的冲击波光环：白 → 金 → 深橙，错峰展开。
    this.addShockwave(point.x, point.y, this.spinnerRadius * 0.62, '#ffffff', 0.38);
    this.addShockwave(
      point.x,
      point.y,
      this.spinnerRadius * 0.95,
      'rgba(255, 226, 158, 0.95)',
      0.56,
    );
    this.addShockwave(point.x, point.y, this.spinnerRadius * 1.4, '#ff9a4d', 0.8);

    // 爆点火花：纯白核心颗粒，数量适中，不挤占粒子池。
    this.particles.burst(point.x, point.y, {
      count: 18,
      color: '#fffdf4',
      speedMin: this.arenaRadius * 0.4,
      speedMax: this.arenaRadius * 1.55,
      sizeMin: 1.6,
      sizeMax: 4.8,
      lifeMin: 0.14,
      lifeMax: 0.42,
      direction: Math.atan2(event.normal.y, event.normal.x),
      spread: Math.PI,
    });

    this.screenFlash = Math.max(this.screenFlash, 0.4);
    this.shake = Math.max(this.shake, 8);

    this.spawnMaxText();
  }

  /**
   * MAX HIT 飘字。
   * 位置取双方机体上方，而不是接触点 / 陀螺中心，避免大字压住机体本体。
   * 单独拆出后，热身期的满力首撞也能只显示文字、不触发顿帧。
   */
  private spawnMaxText(): void {
    if (!this.p1 || !this.p2) return;
    const midX = (this.p1.pos.x + this.p2.pos.x) / 2;
    const topY = Math.min(this.p1.pos.y, this.p2.pos.y);
    this.addFloatingText(
      'MAX HIT',
      '满力重击',
      midX,
      topY - this.spinnerRadius * 2.1,
      'max',
    );
  }

  /**
   * MAX 满力撞击专用顿帧：冻结全局时间 / 物理 / 粒子 / 旋转 0.08s。
   * 冻结瞬间双方机体整枚闪白、屏幕 8px 强震，并叠一记最沉重的金属撞击音。
   * 普通撞击、破招、出界一律不触发顿帧。
   */
  private triggerHitStop(): void {
    this.hitStop = Math.max(this.hitStop, 0.08);
    this.hitStopShake = 8;
    this.shake = 8;
    if (this.p1) this.p1.hitFlash = 1;
    if (this.p2) this.p2.hitFlash = 1;
    this.audio.playHitStop(1);
  }

  private spawnTrail(spinner: Spinner, dt: number): void {
    if (!spinner.launched || spinner.out) return;
    spinner.trailTimer -= dt;
    if (spinner.trailTimer > 0) return;
    const speed = Math.hypot(spinner.vel.x, spinner.vel.y);
    if (
      speed < this.arenaRadius * CONFIG.particles.trailMinSpeedRatio ||
      spinner.spinRatio < 0.1
    ) {
      return;
    }
    spinner.trailTimer = CONFIG.particles.trailInterval;
    this.particles.trail(
      spinner.pos.x - (spinner.vel.x / speed) * spinner.radius * 0.72,
      spinner.pos.y - (spinner.vel.y / speed) * spinner.radius * 0.72,
      spinner.type.colors.accent,
      spinner.spinRatio,
    );
  }

  /**
   * MAX 满力闪电：只在局内冲刺蓄力达到满力阈值时闪烁火花。
   * 松开或破招后 dashCharging 立刻归零，特效自然消失。
   */
  private updateMaxLightningSparks(dt: number): void {
    for (const spinner of [this.p1, this.p2]) {
      if (!spinner) continue;
      const charged =
        spinner.dashCharging &&
        spinner.dashCharge >= CONFIG.dash.maxChargeThreshold &&
        !spinner.out;
      if (!charged) {
        spinner.sparkTimer = 0;
        continue;
      }
      spinner.sparkTimer -= dt;
      if (spinner.sparkTimer > 0) continue;
      spinner.sparkTimer = 0.045;
      const angle = Math.random() * Math.PI * 2;
      const distance = spinner.radius * (1.05 + Math.random() * 0.55);
      this.particles.burst(
        spinner.pos.x + Math.cos(angle) * distance,
        spinner.pos.y + Math.sin(angle) * distance,
        {
          count: 1,
          color: Math.random() < 0.55 ? '#c4b5fd' : '#f5f3ff',
          speedMin: this.arenaRadius * 0.06,
          speedMax: this.arenaRadius * 0.2,
          sizeMin: 1,
          sizeMax: 2.2,
          lifeMin: 0.08,
          lifeMax: 0.2,
        },
      );
    }
  }

  /**
   * 对战中的状态提示只写入 HUD 顶部信息栏的极小文字。
   * 战场内不绘制任何文字弹窗，保证视野绝对干净。
   */
  private setNotice(
    text: string,
    tone: 'neutral' | 'good' | 'warn' | 'danger' = 'neutral',
    durationMs = 1600,
  ): void {
    this.notice = text;
    this.noticeTone = tone;
    // 沿用旧的毫秒时长语义，内部换算为物理时钟秒数。
    this.noticeTimer = Math.max(0.2, durationMs / 1000);
  }

  private addShockwave(x: number, y: number, radius: number, color: string, life: number): void {
    if (this.shockwaves.length > 9) this.shockwaves.shift();
    this.shockwaves.push({ x, y, radius, life, maxLife: life, color });
  }

  private updateShockwaves(dt: number): void {
    for (let i = this.shockwaves.length - 1; i >= 0; i -= 1) {
      const wave = this.shockwaves[i];
      wave.life -= dt;
      wave.radius += this.arenaRadius * 1.55 * dt;
      if (wave.life <= 0) this.shockwaves.splice(i, 1);
    }
  }

  private addImpactFlash(
    x: number,
    y: number,
    radius: number,
    color: string,
    life: number,
  ): void {
    if (this.impactFlashes.length > 7) this.impactFlashes.shift();
    this.impactFlashes.push({ x, y, radius, life, maxLife: life, color });
  }

  private updateImpactFlashes(dt: number): void {
    for (let i = this.impactFlashes.length - 1; i >= 0; i -= 1) {
      const flash = this.impactFlashes[i];
      flash.life -= dt;
      flash.radius += this.arenaRadius * 0.38 * dt;
      if (flash.life <= 0) this.impactFlashes.splice(i, 1);
    }
  }

  /** 飘字队列：容量很小，避免连续碰撞时文字堆满屏幕。 */
  private addFloatingText(
    text: string,
    sub: string,
    x: number,
    y: number,
    tone: FloatingText['tone'],
  ): void {
    if (this.floatingTexts.length > 5) this.floatingTexts.shift();
    const maxLife = tone === 'max' ? 1 : 0.82;
    this.floatingTexts.push({
      text,
      sub,
      x,
      y,
      life: maxLife,
      maxLife,
      tone,
      rise: this.spinnerRadius * (tone === 'max' ? 1.6 : 1.15),
      size: this.spinnerRadius * (tone === 'max' ? 1.32 : 0.82),
    });
  }

  private updateFloatingTexts(dt: number): void {
    for (let i = this.floatingTexts.length - 1; i >= 0; i -= 1) {
      const item = this.floatingTexts[i];
      item.life -= dt;
      if (item.life <= 0) this.floatingTexts.splice(i, 1);
    }
  }

  private endMatch(winnerSide: 1 | 2 | null, reason: string): void {
    if (this.battlePhase === 'ending' || !this.p1 || !this.p2) return;
    this.battlePhase = 'ending';
    this.resultTimer = CONFIG.result.delay;
    this.resultReason = reason;
    this.resultDraw = winnerSide === null;
    this.resultWinnerSide = winnerSide ?? 1;
    this.eliminationGrace = 0;
    this.shake = Math.max(this.shake, CONFIG.camera.outShake);

    if (winnerSide === null) {
      // 平局：双方同时失去胜负，给一次对称的收场冲击，不做单方面碎裂。
      this.shatteredSide = null;
      this.audio.playDraw();
      for (const spinner of [this.p1, this.p2]) {
        this.addShockwave(
          spinner.pos.x,
          spinner.pos.y,
          this.spinnerRadius,
          '#d8c391',
          0.9,
        );
        this.particles.burst(spinner.pos.x, spinner.pos.y, {
          count: 12,
          color: '#e6d6b0',
          speedMin: this.arenaRadius * 0.16,
          speedMax: this.arenaRadius * 0.6,
          sizeMin: 1,
          sizeMax: 2.8,
          lifeMin: 0.3,
          lifeMax: 0.75,
        });
      }
      this.setNotice(`DRAW · ${reason}`, 'warn', 2400);
      this.refreshBattleUI();
      return;
    }

    const loserSide: 1 | 2 = winnerSide === 1 ? 2 : 1;
    const loser = loserSide === 1 ? this.p1 : this.p2;
    this.shatteredSide = loserSide;
    this.audio.playOut();
    this.audio.playShatter();
    this.addShockwave(loser.pos.x, loser.pos.y, this.spinnerRadius, '#ff6952', 0.95);
    this.particles.burst(loser.pos.x, loser.pos.y, {
      count: 18,
      color: '#ff8a6e',
      speedMin: this.arenaRadius * 0.18,
      speedMax: this.arenaRadius * 0.9,
      sizeMin: 1,
      sizeMax: 3.4,
      lifeMin: 0.3,
      lifeMax: 0.85,
    });
    this.spawnShatter(loser);
    this.setNotice(`P${loserSide} 碎裂出局 · ${reason}`, 'danger', 2300);
    this.refreshBattleUI();
  }

  /** 战败方在原地解体：一圈金属碎片向外飞溅并逐渐熄灭。 */
  private spawnShatter(spinner: Spinner): void {
    const palette = [
      spinner.type.colors.light,
      spinner.type.colors.body,
      spinner.type.colors.dark,
      spinner.type.colors.accent,
    ];
    const count = 24;
    for (let i = 0; i < count; i += 1) {
      const angle = (i / count) * Math.PI * 2 + randomBetween(-0.2, 0.2);
      const speed = this.arenaRadius * randomBetween(0.4, 1.45);
      const maxLife = randomBetween(0.6, 1.3);
      this.shards.push({
        x: spinner.pos.x + Math.cos(angle) * spinner.radius * 0.35,
        y: spinner.pos.y + Math.sin(angle) * spinner.radius * 0.35,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        size: spinner.radius * randomBetween(0.12, 0.34),
        length: spinner.radius * randomBetween(0.32, 0.95),
        angle,
        spin: randomBetween(-13, 13),
        life: maxLife,
        maxLife,
        color: palette[i % palette.length],
        edge: i % 3 === 0 ? '#fff6de' : 'rgba(0, 0, 0, 0.55)',
      });
    }
    this.particles.burst(spinner.pos.x, spinner.pos.y, {
      count: 20,
      color: '#fff3d8',
      speedMin: this.arenaRadius * 0.45,
      speedMax: this.arenaRadius * 1.5,
      sizeMin: 1.4,
      sizeMax: 3.8,
      lifeMin: 0.14,
      lifeMax: 0.42,
    });
  }

  private updateShards(dt: number): void {
    for (let i = this.shards.length - 1; i >= 0; i -= 1) {
      const shard = this.shards[i];
      shard.life -= dt;
      if (shard.life <= 0) {
        this.shards.splice(i, 1);
        continue;
      }
      const damping = Math.exp(-1.6 * dt);
      shard.vx *= damping;
      shard.vy *= damping;
      shard.x += shard.vx * dt;
      shard.y += shard.vy * dt;
      shard.angle += shard.spin * dt;
    }
  }

  private drawShards(): void {
    const ctx = this.ctx;
    ctx.save();
    for (const shard of this.shards) {
      const progress = shard.life / shard.maxLife;
      ctx.globalAlpha = Math.min(1, progress * 1.8);
      ctx.save();
      ctx.translate(shard.x, shard.y);
      ctx.rotate(shard.angle);
      ctx.beginPath();
      ctx.moveTo(shard.length, 0);
      ctx.lineTo(-shard.length * 0.35, shard.size);
      ctx.lineTo(-shard.length * 0.5, -shard.size * 0.6);
      ctx.closePath();
      ctx.fillStyle = shard.color;
      ctx.fill();
      ctx.strokeStyle = shard.edge;
      ctx.lineWidth = Math.max(0.6, shard.size * 0.22);
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  private showResult(playSound = true): void {
    if (!this.p1 || !this.p2) return;
    this.state = 'result';
    this.hitStop = 0;
    this.hitStopShake = 0;
    this.entries = null;
    const draw = this.resultDraw;
    const winnerSide = this.resultWinnerSide;
    const loserSide: 1 | 2 = winnerSide === 1 ? 2 : 1;
    const winner = winnerSide === 1 ? this.p1 : this.p2;
    const winnerType = this.types[winnerSide - 1];
    const loserType = this.types[loserSide - 1];
    const view: ResultView = {
      draw,
      winnerSide,
      winnerName: draw ? 'DRAW' : winnerType.name,
      winnerType: draw ? this.types[0] : winnerType,
      loserName: draw ? '双方同时出局' : `P${loserSide} ${loserType.name}`,
      reason: this.resultReason,
      remainingSpin: draw
        ? ((this.p1.spinRatio + this.p2.spinRatio) / 2) * 100
        : winner.spinRatio * 100,
      maxRpm: winner.maxRpm,
      hits: draw ? this.p1.hitCount + this.p2.hitCount : winner.hitCount,
      duration: this.elapsed,
      mode: this.mode,
      p1Name: this.types[0].name,
      p2Name: this.types[1].name,
      p1Type: this.types[0],
      p2Type: this.types[1],
      p1Spin: this.p1.spinRatio * 100,
      p2Spin: this.p2.spinRatio * 100,
    };
    this.particles.clear();
    this.shockwaves = [];
    this.impactFlashes = [];
    this.floatingTexts = [];
    this.screenFlash = 0;
    this.shards = [];
    if (playSound) {
      if (draw) this.audio.playDraw();
      else this.audio.playWin();
    }
    this.ui.showResult(view);
  }

  private getFighterView(spinner: Spinner): FighterHudView {
    return {
      name: spinner.type.name,
      code: spinner.type.code,
      category: spinner.type.category,
      spin: spinner.spinRatio * 100,
      rpm: spinner.rpm,
      charge: spinner.charge,
      tier: spinner.tier,
      locked: spinner.chargeLocked,
      dashCharge: spinner.dashCharge,
      dashCooldown: spinner.dashCooldown,
      dashCharging: spinner.dashCharging,
      dashLockout: spinner.dashLockout,
    };
  }

  private getBattleView(): BattleView {
    if (!this.p1 || !this.p2) throw new Error('Battle view requested without fighters');
    let countdownText: string | null = null;
    let countdownLabel = '';
    let phaseMode: BattleView['phaseMode'] = 'combat';
    let phaseLabel = 'LIVE';
    let hint = 'WASD / 方向键走位 · 按住蓄力键冲刺撞击';

    if (this.battlePhase === 'intro') {
      phaseMode = 'intro';
      phaseLabel = 'STANDBY';
      hint = '战场校准 · 双方机体即将从场外飞入';
    } else if (this.battlePhase === 'entry') {
      phaseMode = 'launch';
      phaseLabel = 'ENTRY';
      hint = '双方机体飞入 · 落地后等待发射';
    } else if (this.battlePhase === 'ready') {
      phaseMode = 'ready';
      phaseLabel = 'READY';
      hint =
        this.mode === 'cpu'
          ? '按 SPACE 开始倒计时 · AI 会自动开始 · W/S 可先瞄准'
          : '任意一方按下发射键开始倒计时 · P1 SPACE / P2 小键盘 0';
    } else if (this.battlePhase === 'countdown') {
      countdownText = String(
        Math.max(1, Math.min(3, Math.ceil(this.countdownTimer - 0.22))),
      );
      countdownLabel = '瞄准 · 蓄力';
      phaseMode = 'countdown';
      phaseLabel = 'CHARGING';
      hint =
        this.mode === 'cpu'
          ? 'W / S 瞄准 · SPACE 蓄力 · 松开锁定档位'
          : 'P1 W/S + SPACE · P2 ↑/↓ + 小键盘 0 · 松开锁定档位';
    } else if (this.battlePhase === 'ending') {
      phaseMode = 'ending';
      phaseLabel = 'KO';
      hint = '胜负已分 · 正在生成对局记录';
    } else if (this.goTimer > 0) {
      countdownText = 'GO';
      countdownLabel = '释放';
      phaseMode = 'combat';
      phaseLabel = 'LAUNCH';
      hint = '走位接手 · 发射初速仍在延续';
    } else if (this.warmup > 0) {
      phaseMode = 'warmup';
      phaseLabel = 'WARM-UP';
      hint = '热身接触 · 击退与蓄力伤害暂时降低';
    }

    return {
      p1: this.getFighterView(this.p1),
      p2: this.getFighterView(this.p2),
      phaseLabel,
      phaseMode,
      countdownText,
      countdownLabel,
      hint,
      mode: this.mode,
      notice: this.notice,
      noticeTone: this.noticeTone,
      timeLeft:
        this.battlePhase === 'fight'
          ? Math.max(0, CONFIG.match.timeLimit - this.elapsed)
          : null,
    };
  }

  private refreshBattleUI(): void {
    if (this.state !== 'battle' || !this.p1 || !this.p2) return;
    this.ui.updateBattle(this.getBattleView());
  }

  private tick(dt: number): void {
    if (!this.p1 || !this.p2) return;
    if (this.battlePhase === 'intro') this.tickIntro(dt);
    else if (this.battlePhase === 'entry') this.tickEntry(dt);
    else if (this.battlePhase === 'ready') this.tickReady(dt);
    else if (this.battlePhase === 'countdown') this.tickCountdown(dt);
    else if (this.battlePhase === 'fight') this.tickFight(dt);
    else if (this.battlePhase === 'ending') this.tickEnding(dt);

    this.p1.updateVisual(dt);
    this.p2.updateVisual(dt);
    this.particles.update(dt);
    if (this.noticeTimer > 0) {
      this.noticeTimer = Math.max(0, this.noticeTimer - dt);
      if (this.noticeTimer === 0) this.notice = '';
    }
    this.updateShockwaves(dt);
    this.updateImpactFlashes(dt);
    this.updateFloatingTexts(dt);
    this.updateShards(dt);
    this.screenFlash = Math.max(0, this.screenFlash - dt * 2.4);
  }

  private frame = (now: number): void => {
    const raw = Math.min(0.05, Math.max(0, (now - this.lastTime) / 1000));
    this.lastTime = now;

    // 顿帧（MAX 撞击专用 0.08s）：物理、粒子、旋转、全局时间全部 dt=0；只保留强震与闪白。
    if (this.hitStop > 0) {
      this.hitStop = Math.max(0, this.hitStop - raw);
      this.accumulator = 0;
      if (this.hitStop > 0) {
        this.render();
        requestAnimationFrame(this.frame);
        return;
      }
      this.hitStopShake = 0;
    }

    this.screenTime += raw;
    this.shake *= Math.exp(-CONFIG.camera.shakeDecay * raw);

    if (this.state === 'battle') {
      this.accumulator = Math.min(this.accumulator + raw, 0.1);
      let steps = 0;
      // 一旦本次 tick 触发顿帧，立刻停止补帧，避免冻结期间继续推进物理。
      while (
        this.accumulator >= CONFIG.timestep &&
        steps < 8 &&
        this.state === 'battle' &&
        this.hitStop <= 0
      ) {
        this.tick(CONFIG.timestep);
        this.accumulator -= CONFIG.timestep;
        steps += 1;
      }
      if (this.state !== 'battle' || this.hitStop > 0) this.accumulator = 0;
    } else {
      this.accumulator = 0;
      if (this.state === 'select') this.updateSelection(raw);
    }

    this.hudTimer += raw;
    if (this.state === 'battle' && this.hudTimer >= 0.05) {
      this.hudTimer = 0;
      this.refreshBattleUI();
    }

    this.render();
    requestAnimationFrame(this.frame);
  };

  private resize(): void {
    const rect = this.canvas.getBoundingClientRect();
    const oldRadius = this.arenaRadius;
    this.width = Math.max(1, rect.width);
    this.height = Math.max(1, rect.height);
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(this.width * this.dpr);
    this.canvas.height = Math.round(this.height * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.ctx.imageSmoothingEnabled = true;

    this.centerX = this.width / 2;
    this.centerY = this.height * CONFIG.arena.centerY;
    this.arenaRadius = Math.min(
      (this.height * CONFIG.arena.heightRatio) / 2,
      (this.width * CONFIG.arena.widthRatio) / 2,
      CONFIG.arena.maxRadius,
    );
    this.spinnerRadius = getSpinnerRadius(this.arenaRadius);

    if (this.p1 && this.p2 && oldRadius > 0) {
      const ratio = this.arenaRadius / oldRadius;
      for (const spinner of [this.p1, this.p2]) {
        spinner.pos.x *= ratio;
        spinner.pos.y *= ratio;
        spinner.vel.x *= ratio;
        spinner.vel.y *= ratio;
        spinner.radius = this.spinnerRadius * spinner.type.radiusScale;
      }
      if (this.entries) {
        const spawn = getSpawnDistance(this.arenaRadius);
        const reach = this.centerX + Math.max(this.p1.radius, this.p2.radius) * 2.4;
        const arc = this.arenaRadius * 0.3;
        for (const entry of this.entries) {
          const dir = entry.side === 1 ? -1 : 1;
          entry.fromX = dir * reach;
          entry.fromY = dir * arc * 0.55;
          entry.controlX = dir * spawn * 1.55;
          entry.controlY = dir * arc;
          entry.toX = dir * spawn;
          entry.toY = 0;
        }
      }
      if (
        this.battlePhase === 'intro' ||
        this.battlePhase === 'ready' ||
        this.battlePhase === 'countdown'
      ) {
        const spawn = getSpawnDistance(this.arenaRadius);
        this.p1.pos.x = -spawn;
        this.p1.pos.y = 0;
        this.p2.pos.x = spawn;
        this.p2.pos.y = 0;
      }
    }
    this.particles.clear();
    this.createDust();
  }

  private createDust(): void {
    const count = 34;
    this.dust = Array.from({ length: count }, () => ({
      x: Math.random(),
      y: Math.random(),
      size: randomBetween(0.5, 1.8),
      phase: Math.random() * Math.PI * 2,
      speed: randomBetween(0.15, 0.65),
    }));
  }

  private drawDust(): void {
    const ctx = this.ctx;
    ctx.save();
    for (const mote of this.dust) {
      const x = mote.x * this.width;
      const y = (mote.y * this.height + Math.sin(this.screenTime * mote.speed + mote.phase) * 10) % this.height;
      const alpha = 0.08 + Math.max(0, Math.sin(this.screenTime * 0.8 + mote.phase)) * 0.18;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#dfe6d7';
      ctx.beginPath();
      ctx.arc(x, y, mote.size, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  private render(): void {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);
    this.drawDust();

    ctx.save();
    let shakeX = 0;
    let shakeY = 0;
    // 顿帧时至少保持 5px 强震；普通震动仍按衰减曲线自然收敛。
    const shakeAmount =
      this.hitStop > 0 ? Math.max(this.shake, this.hitStopShake) : this.shake;
    if (shakeAmount > 0.08) {
      const angle = Math.random() * Math.PI * 2;
      shakeX = Math.cos(angle) * shakeAmount;
      shakeY = Math.sin(angle) * shakeAmount;
    }
    if (shakeX !== 0 || shakeY !== 0) ctx.translate(shakeX, shakeY);

    // 初始布局或极小视口下画布可能暂时为 0，跳过硬绘制避免负半径异常。
    if (this.arenaRadius >= 24) {
      if (this.state === 'menu') {
        this.drawArena();
        this.drawIdleSpinners();
      } else if (this.state === 'select') {
        // 选人页只保留圆桌底纹；五款模型由卡片画布呈现，避免背景巨影透过半透明卡面。
        this.drawArena();
      } else if (this.state === 'battle') {
        this.drawBattleScene();
      } else if (this.state === 'result') {
        this.drawResultScene();
      }
    }
    ctx.restore();

    // MAX 撞击的整屏爆闪：叠加在震动层之外，顿帧期间保持峰值。
    if (this.screenFlash > 0.001) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = Math.min(0.62, this.screenFlash * 0.78);
      ctx.fillStyle = '#fff7e8';
      ctx.fillRect(0, 0, this.width, this.height);
      ctx.restore();
    }
  }

  private drawArena(): void {
    const ctx = this.ctx;
    const cx = this.centerX;
    const cy = this.centerY;
    const radius = this.arenaRadius;
    if (!Number.isFinite(radius) || radius < 24) return;

    const outerGlow = ctx.createRadialGradient(cx, cy, radius * 0.82, cx, cy, radius * 1.24);
    outerGlow.addColorStop(0, 'rgba(174, 149, 96, 0)');
    outerGlow.addColorStop(0.48, 'rgba(174, 149, 96, 0.05)');
    outerGlow.addColorStop(0.56, 'rgba(223, 203, 153, 0.14)');
    outerGlow.addColorStop(1, 'rgba(174, 149, 96, 0)');
    ctx.fillStyle = outerGlow;
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 1.25, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.beginPath();
    ctx.arc(cx, cy + radius * 0.025, radius + radius * 0.045, 0, Math.PI * 2);
    ctx.fill();

    const rim = ctx.createRadialGradient(
      cx - radius * 0.24,
      cy - radius * 0.3,
      radius * 0.72,
      cx,
      cy,
      radius * 1.02,
    );
    rim.addColorStop(0, '#38392f');
    rim.addColorStop(0.72, '#1b1e18');
    rim.addColorStop(0.92, '#4c4735');
    rim.addColorStop(0.97, '#1c1d16');
    rim.addColorStop(1, '#0a0c09');
    ctx.fillStyle = rim;
    ctx.beginPath();
    ctx.arc(cx, cy, radius + 4, 0, Math.PI * 2);
    ctx.fill();

    const floor = ctx.createRadialGradient(
      cx - radius * 0.19,
      cy - radius * 0.23,
      radius * 0.02,
      cx,
      cy,
      radius,
    );
    floor.addColorStop(0, '#33362f');
    floor.addColorStop(0.28, '#242821');
    floor.addColorStop(0.63, '#161a15');
    floor.addColorStop(0.88, '#0f120e');
    floor.addColorStop(1, '#090b09');
    ctx.fillStyle = floor;
    ctx.beginPath();
    ctx.arc(cx, cy, radius - 2, 0, Math.PI * 2);
    ctx.fill();

    const sheen = ctx.createLinearGradient(
      cx - radius,
      cy - radius,
      cx + radius,
      cy + radius,
    );
    sheen.addColorStop(0, 'rgba(243, 232, 203, 0.055)');
    sheen.addColorStop(0.34, 'rgba(243, 232, 203, 0.008)');
    sheen.addColorStop(0.7, 'rgba(0, 0, 0, 0.08)');
    sheen.addColorStop(1, 'rgba(0, 0, 0, 0.18)');
    ctx.fillStyle = sheen;
    ctx.beginPath();
    ctx.arc(cx, cy, radius - 2, 0, Math.PI * 2);
    ctx.fill();

    // 外圈警示环
    ctx.strokeStyle = 'rgba(194, 177, 139, 0.16)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, radius - 3.5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, radius - 7, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(218, 201, 162, 0.16)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, radius - radius * 0.065, 0, Math.PI * 2);
    ctx.stroke();

    // 缓慢旋转的刻度环
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(this.screenTime * 0.014);
    for (let i = 0; i < 72; i += 1) {
      const angle = (i / 72) * Math.PI * 2;
      const major = i % 6 === 0;
      const tick = major ? radius * 0.024 : radius * 0.012;
      ctx.strokeStyle = major
        ? 'rgba(219, 202, 164, 0.22)'
        : 'rgba(219, 202, 164, 0.09)';
      ctx.lineWidth = major ? 1.2 : 0.7;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * (radius * 0.91), Math.sin(angle) * (radius * 0.91));
      ctx.lineTo(
        Math.cos(angle) * (radius * 0.91 - tick),
        Math.sin(angle) * (radius * 0.91 - tick),
      );
      ctx.stroke();
    }
    ctx.restore();

    // 同心雕刻
    ctx.strokeStyle = 'rgba(223, 209, 175, 0.12)';
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 10]);
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 0.76, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = 'rgba(223, 209, 175, 0.09)';
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 0.57, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(223, 209, 175, 0.12)';
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 0.34, 0, Math.PI * 2);
    ctx.stroke();

    // 四段弧线标记
    ctx.strokeStyle = 'rgba(192, 170, 126, 0.16)';
    ctx.lineWidth = 1.3;
    for (let i = 0; i < 4; i += 1) {
      const start = i * (Math.PI / 2) + 0.18;
      ctx.beginPath();
      ctx.arc(cx, cy, radius * 0.69, start, start + 0.66);
      ctx.stroke();
    }

    // 中心罗盘
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(-this.screenTime * 0.04);
    ctx.strokeStyle = 'rgba(209, 190, 148, 0.24)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.16, 0, Math.PI * 2);
    ctx.stroke();
    ctx.rotate(Math.PI / 4);
    ctx.strokeStyle = 'rgba(113, 226, 196, 0.18)';
    ctx.beginPath();
    for (let i = 0; i < 4; i += 1) {
      const angle = i * (Math.PI / 2);
      const length = radius * 0.095;
      ctx.moveTo(0, 0);
      ctx.lineTo(Math.cos(angle) * length, Math.sin(angle) * length);
      ctx.moveTo(0, 0);
      ctx.lineTo(Math.cos(angle + Math.PI / 4) * length * 0.48, Math.sin(angle + Math.PI / 4) * length * 0.48);
    }
    ctx.stroke();
    ctx.restore();

    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(215, 199, 160, 0.2)';
    ctx.font = '500 9px "Barlow Condensed", "Noto Sans SC", sans-serif';
    ctx.fillText('GYROSCOPIC DUEL ARENA', cx, cy + radius * 0.455);
    ctx.fillStyle = 'rgba(215, 199, 160, 0.12)';
    ctx.font = '500 8px "Barlow Condensed", sans-serif';
    ctx.fillText('MODEL 07 / Ø 75%', cx, cy + radius * 0.49);
  }

  private drawIdleSpinners(): void {
    const ctx = this.ctx;
    const angle = this.screenTime * 0.16;
    const radius = this.arenaRadius;
    const orbit = radius * 0.43;
    const type1 = this.selection ? GYRO_TYPES[this.selection.p1Index] : GYRO_TYPES[0];
    const type2 = this.selection ? GYRO_TYPES[this.selection.p2Index] : GYRO_TYPES[1];
    const spinnerSize = getSpinnerRadius(radius) * 1.45;
    for (let i = 0; i < 2; i += 1) {
      const a = angle + i * Math.PI;
      const x = this.centerX + Math.cos(a) * orbit;
      const y = this.centerY + Math.sin(a) * orbit * 0.58;
      drawGyro(ctx, i === 0 ? type1 : type2, x, y, spinnerSize, {
        rotation: this.screenTime * (i === 0 ? 1.2 : -0.95),
        spinRatio: 0.9,
        side: (i + 1) as 1 | 2,
        alpha: 0.6,
        time: this.screenTime,
      });
    }

    ctx.save();
    ctx.strokeStyle = 'rgba(209, 192, 155, 0.08)';
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 14]);
    ctx.beginPath();
    ctx.ellipse(this.centerX, this.centerY, orbit, orbit * 0.58, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  private drawBattleScene(): void {
    this.drawArena();
    if (!this.p1 || !this.p2) return;
    const ctx = this.ctx;

    // 战斗实体使用以圆心为原点的局部坐标，统一平移后绘制。
    ctx.save();
    ctx.translate(this.centerX, this.centerY);

    if (this.battlePhase === 'intro') {
      // 空场准备：机体与瞄准箭头都不出现，场地保持干净。
    } else if (
      this.battlePhase === 'ready' ||
      this.battlePhase === 'countdown'
    ) {
      this.drawSpawnPad(this.p1);
      this.drawSpawnPad(this.p2);
      this.drawAimArrow(this.p1);
      this.drawAimArrow(this.p2);
    } else if (this.battlePhase === 'entry' && this.entries) {
      for (const entry of this.entries) {
        const spinner = entry.side === 1 ? this.p1 : this.p2;
        this.drawSpawnPad(spinner, entry.toX, entry.toY);
        this.drawEntryTrail(spinner);
      }
    }

    const spinners = [this.p2, this.p1];
    for (const spinner of spinners) {
      // 入场准备阶段场地为空，直到飞入阶段才绘制机体。
      if (this.battlePhase === 'intro') continue;
      // 战败方已解体：用碎片替代完整机体，胜利方继续留在场上旋转。
      if (this.battlePhase === 'ending' && this.shatteredSide === spinner.side) continue;
      if (spinner.dashActive > 0) this.drawDashTrail(spinner);
      spinner.draw(ctx, this.screenTime, this.battlePhase === 'ending' ? 0.85 : 1);
      if (
        spinner.dashCharging &&
        spinner.dashCharge >= CONFIG.dash.maxChargeThreshold &&
        this.battlePhase === 'fight'
      ) {
        this.drawMaxLightning(spinner);
      }
      if (spinner.dashCharging && this.battlePhase === 'fight') {
        this.drawDashChargeAura(spinner);
      }
    }

    if (this.battlePhase === 'fight') this.drawDashMeters();

    this.particles.draw(ctx);
    this.drawShards();
    this.drawShockwaves();
    this.drawImpactFlashes();
    this.drawFloatingTexts();
    ctx.restore();
  }

  /** 入场飞行的高亮拖尾与残影。 */
  private drawEntryTrail(spinner: Spinner): void {
    const speed = Math.hypot(spinner.vel.x, spinner.vel.y);
    if (speed < this.arenaRadius * 0.35) return;
    const ctx = this.ctx;
    const nx = spinner.vel.x / speed;
    const ny = spinner.vel.y / speed;
    const color = SIDE_COLORS[spinner.side].main;
    const trailLength =
      spinner.radius * 2.2 + Math.min(this.arenaRadius * 0.6, speed * 0.075);

    ctx.save();
    const tail = ctx.createLinearGradient(
      spinner.pos.x,
      spinner.pos.y,
      spinner.pos.x - nx * trailLength,
      spinner.pos.y - ny * trailLength,
    );
    tail.addColorStop(0, 'rgba(255, 252, 238, 0.92)');
    tail.addColorStop(0.24, color);
    tail.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.globalAlpha = 0.62;
    ctx.strokeStyle = tail;
    ctx.lineWidth = spinner.radius * 0.58;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(spinner.pos.x, spinner.pos.y);
    ctx.lineTo(
      spinner.pos.x - nx * trailLength,
      spinner.pos.y - ny * trailLength,
    );
    ctx.stroke();

    for (let i = 3; i >= 1; i -= 1) {
      const distance = spinner.radius * (0.85 + i * 0.72);
      drawGyro(
        ctx,
        spinner.type,
        spinner.pos.x - nx * distance,
        spinner.pos.y - ny * distance,
        spinner.radius * (1 - i * 0.035),
        {
          rotation: spinner.visualAngle - i * 0.24,
          spinRatio: spinner.spinRatio,
          side: spinner.side,
          alpha: 0.24 - i * 0.05,
          time: this.screenTime,
        },
      );
    }
    ctx.restore();
  }

  /** 陀螺正下方的冲刺面板：上条为蓄力，下条为冷却，双方都能读到。 */
  private drawDashMeters(): void {
    if (!this.p1 || !this.p2) return;
    const ctx = this.ctx;

    for (const spinner of [this.p1, this.p2]) {
      if (spinner.out) continue;
      const color = SIDE_COLORS[spinner.side].main;
      // 破招封锁：蓄力条必须立刻清空，恢复表现与冲刺冷却完全一致。
      const lockout = spinner.dashLockout > 0;
      const charging = spinner.dashCharging && !lockout;
      const width = spinner.radius * (charging ? 2.75 : 2.45);
      const x = spinner.pos.x - width / 2;
      const y = spinner.pos.y + spinner.radius + 10;
      const charge = charging ? spinner.dashCharge : 0;
      // 左到右回充：破招封锁与冲刺冷却共用同一条灰色恢复条。
      const recover = lockout
        ? 1 - clamp(spinner.dashLockout / CONFIG.dash.breakCooldown, 0, 1)
        : spinner.dashCooldown <= 0
          ? 1
          : 1 - spinner.dashCooldown / CONFIG.dash.cooldown;
      const ready = !lockout && spinner.dashCooldown <= 0 && !charging;
      const warnBlink = (Math.sin(this.screenTime * (22 + charge * 18)) + 1) / 2;

      ctx.save();
      ctx.fillStyle = charging
        ? 'rgba(35, 12, 9, 0.82)'
        : 'rgba(4, 7, 5, 0.72)';
      ctx.fillRect(x - 5, y - 3, width + 10, 13);
      ctx.strokeStyle = charging
        ? `rgba(255, 112, 86, ${0.3 + warnBlink * 0.45})`
        : 'rgba(230, 218, 190, 0.16)';
      ctx.lineWidth = charging ? 1.4 : 1;
      ctx.strokeRect(x - 5, y - 3, width + 10, 13);

      // 蓄力条：前摇时使用红白警告色，扩大宽度并闪烁。
      ctx.fillStyle = 'rgba(235, 225, 200, 0.13)';
      ctx.fillRect(x, y, width, 3);
      if (charge > 0) {
        ctx.fillStyle = warnBlink > 0.5 ? '#fff1d8' : '#ff7a5e';
        ctx.fillRect(x, y, width * charge, 3);
        ctx.globalAlpha = 0.45 + warnBlink * 0.45;
        ctx.fillStyle = color;
        ctx.fillRect(x, y, width * charge, 1);
        ctx.globalAlpha = 1;
      }

      // 恢复条：越满代表越接近可用。
      // 破招封锁期间与冲刺冷却完全一致：灰色条从左到右回充，不显示红色破招闪色。
      ctx.fillStyle = 'rgba(235, 225, 200, 0.1)';
      ctx.fillRect(x, y + 6, width, 2);
      ctx.fillStyle = lockout
        ? 'rgba(216, 195, 145, 0.58)'
        : spinner.dashBreakFlash > 0.01
          ? '#ff8067'
          : ready
            ? color
            : 'rgba(216, 195, 145, 0.58)';
      ctx.fillRect(x, y + 6, width * Math.max(0, Math.min(1, recover)), 2);

      // 就绪时的呼吸光。
      if (ready) {
        ctx.globalAlpha = 0.18 + (Math.sin(this.screenTime * 5 + spinner.side) + 1) * 0.12;
        ctx.fillStyle = color;
        ctx.fillRect(x - 2, y - 1, width + 4, 11);
        ctx.globalAlpha = 1;
      }
      ctx.restore();
    }
  }

  /** 冲刺蓄力前摇：内聚警告环 + 高频红白边缘闪烁，让对手能立刻读出来。 */
  private drawDashChargeAura(spinner: Spinner): void {
    const ctx = this.ctx;
    const charge = spinner.dashCharge;
    const blink = (Math.sin(this.screenTime * (34 + charge * 18) + spinner.side * 2.3) + 1) / 2;
    const color = SIDE_COLORS[spinner.side].main;

    ctx.save();
    ctx.translate(spinner.pos.x, spinner.pos.y);

    // 陀螺边缘被警告色包裹，蓄力越满越明显。
    const dangerGlow = ctx.createRadialGradient(
      0,
      0,
      spinner.radius * 0.62,
      0,
      0,
      spinner.radius * 1.35,
    );
    dangerGlow.addColorStop(0, 'rgba(255, 92, 74, 0)');
    dangerGlow.addColorStop(0.7, `rgba(255, 92, 74, ${0.1 + charge * 0.16})`);
    dangerGlow.addColorStop(1, 'rgba(255, 92, 74, 0)');
    ctx.globalAlpha = 0.55 + blink * 0.35;
    ctx.fillStyle = dangerGlow;
    ctx.beginPath();
    ctx.arc(0, 0, spinner.radius * 1.35, 0, Math.PI * 2);
    ctx.fill();

    // 向内聚拢的光环：三圈错峰收缩。
    for (let i = 0; i < 3; i += 1) {
      const phase = (this.screenTime * 1.6 + i / 3) % 1;
      const radius = spinner.radius * (1.3 + (1 - phase) * 1.25);
      ctx.globalAlpha = (1 - phase) * (0.18 + charge * 0.24);
      ctx.strokeStyle = i === 1 ? '#ff5a4a' : '#fff3d6';
      ctx.lineWidth = 1.2 + charge * 1.5;
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.stroke();
    }

    // 高频闪烁的警告边缘。
    const rimColor = blink > 0.5 ? '#fff4db' : '#ff5a4a';
    ctx.globalAlpha = (0.3 + blink * 0.45) * (0.6 + charge * 0.4);
    ctx.strokeStyle = rimColor;
    ctx.lineWidth = 1.8 + charge * 2.1;
    ctx.beginPath();
    ctx.arc(0, 0, spinner.radius + 2 + blink * 2.5, 0, Math.PI * 2);
    ctx.stroke();

    ctx.globalAlpha = 0.24 + blink * 0.2;
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, spinner.radius + 7 + blink * 2, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  /** 冲刺中的高速残影与亮色拖尾。 */
  private drawDashTrail(spinner: Spinner): void {
    if (spinner.dashActive <= 0) return;
    const speed = Math.hypot(spinner.vel.x, spinner.vel.y);
    if (speed < this.arenaRadius * 0.3) return;

    const ctx = this.ctx;
    const nx = spinner.vel.x / speed;
    const ny = spinner.vel.y / speed;
    const life = Math.max(
      0,
      Math.min(1, spinner.dashActive / CONFIG.dash.activeDuration),
    );
    const color = SIDE_COLORS[spinner.side].main;
    const trailLength =
      spinner.radius * (1.4 + spinner.dashPower * 1.8) * (0.45 + life * 0.55);

    ctx.save();
    // 贴地的高亮速度拖尾。
    const tailGradient = ctx.createLinearGradient(
      spinner.pos.x - nx * spinner.radius * 0.4,
      spinner.pos.y - ny * spinner.radius * 0.4,
      spinner.pos.x - nx * (spinner.radius * 0.4 + trailLength),
      spinner.pos.y - ny * (spinner.radius * 0.4 + trailLength),
    );
    tailGradient.addColorStop(0, 'rgba(255, 249, 233, 0.85)');
    tailGradient.addColorStop(0.32, color);
    tailGradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.globalAlpha = 0.22 + life * 0.34;
    ctx.strokeStyle = tailGradient;
    ctx.lineWidth = spinner.radius * (0.5 + spinner.dashPower * 0.32);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(
      spinner.pos.x - nx * spinner.radius * 0.3,
      spinner.pos.y - ny * spinner.radius * 0.3,
    );
    ctx.lineTo(
      spinner.pos.x - nx * (spinner.radius * 0.4 + trailLength),
      spinner.pos.y - ny * (spinner.radius * 0.4 + trailLength),
    );
    ctx.stroke();

    // 三层残影，越远越淡。
    for (let i = 3; i >= 1; i -= 1) {
      const distance =
        spinner.radius * (0.5 + i * 0.62) * (0.65 + spinner.dashPower * 0.4);
      drawGyro(
        ctx,
        spinner.type,
        spinner.pos.x - nx * distance,
        spinner.pos.y - ny * distance,
        spinner.radius * (1 - i * 0.035),
        {
          rotation: spinner.visualAngle - i * 0.2,
          spinRatio: spinner.spinRatio,
          side: spinner.side,
          alpha: life * (0.14 - i * 0.025),
          time: this.screenTime - i * 0.02,
        },
      );
    }
    ctx.restore();
  }

  /**
   * MAX 满力闪电：蓝紫高压电弧 + 贴体电流环。
   * 时间片伪随机保证高频闪烁，全部用线段绘制，不依赖 shadowBlur。
   */
  private drawMaxLightning(spinner: Spinner): void {
    if (spinner.out) return;
    const ctx = this.ctx;
    const r = spinner.radius;
    const time = this.screenTime;
    const seedBase = Math.floor(time * 26) * 7.13 + spinner.side * 19.7;
    const hash = (n: number): number => {
      const x = Math.sin(seedBase + n * 12.9898) * 43758.5453;
      return x - Math.floor(x);
    };
    const accent = spinner.type.colors.accent;
    const boltCount = 6;

    ctx.save();
    ctx.translate(spinner.pos.x, spinner.pos.y);
    ctx.globalCompositeOperation = 'lighter';

    // 蓝紫电场底光。
    const glow = ctx.createRadialGradient(0, 0, r * 0.55, 0, 0, r * 2.05);
    glow.addColorStop(0, 'rgba(150, 120, 255, 0)');
    glow.addColorStop(0.55, 'rgba(138, 108, 255, 0.22)');
    glow.addColorStop(1, 'rgba(110, 90, 255, 0)');
    ctx.globalAlpha = 0.75 + Math.sin(time * 30) * 0.15;
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(0, 0, r * 2.05, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;

    // 放射状电弧：每帧按时间片重新生成。
    for (let b = 0; b < boltCount; b += 1) {
      const angle = (b / boltCount) * Math.PI * 2 + hash(b) * 0.75;
      const reach = r * (1.35 + hash(b + 40) * 0.75);
      const segments = 5;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * r * 0.92, Math.sin(angle) * r * 0.92);
      for (let i = 1; i <= segments; i += 1) {
        const t = i / segments;
        const dist = r * 0.92 + (reach - r * 0.92) * t;
        const jitter = (hash(b * 17 + i) - 0.5) * r * 0.34 * (1 - t * 0.35);
        const a = angle + (hash(b * 29 + i) - 0.5) * 0.42;
        ctx.lineTo(
          Math.cos(a) * dist - Math.sin(a) * jitter,
          Math.sin(a) * dist + Math.cos(a) * jitter,
        );
      }
      // 宽而暗的紫色辉光 + 细白核心，两层即可兼顾亮度与性能。
      ctx.globalAlpha = 0.4;
      ctx.strokeStyle = '#8b6cff';
      ctx.lineWidth = Math.max(2.4, r * 0.11);
      ctx.stroke();
      ctx.globalAlpha = 0.95;
      ctx.strokeStyle = b % 3 === 0 ? accent : '#f4f0ff';
      ctx.lineWidth = Math.max(0.9, r * 0.036);
      ctx.stroke();
    }

    // 贴体电流环：两圈破碎的电弧。
    for (let ring = 0; ring < 2; ring += 1) {
      ctx.beginPath();
      const steps = 14;
      for (let i = 0; i <= steps; i += 1) {
        const a = (i / steps) * Math.PI * 2;
        const rr = r * (1.1 + ring * 0.2) + (hash(ring * 50 + i) - 0.5) * r * 0.16;
        const px = Math.cos(a) * rr;
        const py = Math.sin(a) * rr;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.globalAlpha = ring === 0 ? 0.75 : 0.4;
      ctx.strokeStyle = ring === 0 ? '#c4b5fd' : accent;
      ctx.lineWidth = Math.max(1, r * 0.03);
      ctx.stroke();
    }

    ctx.globalAlpha = 1;
    ctx.restore();
  }

  private drawSpawnPad(
    spinner: Spinner,
    x = spinner.pos.x,
    y = spinner.pos.y,
  ): void {
    const ctx = this.ctx;
    const color = SIDE_COLORS[spinner.side].main;
    const pulse = 0.5 + Math.sin(this.screenTime * 2.2 + spinner.side) * 0.12;
    ctx.save();
    ctx.translate(x, y);
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.22 + pulse * 0.2;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([3, 7]);
    ctx.beginPath();
    ctx.arc(0, 0, spinner.radius * 1.75, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 0.5;
    ctx.beginPath();
    ctx.arc(0, 0, spinner.radius * 1.38, -0.35, 0.7);
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.font = '600 9px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.globalAlpha = 0.56;
    ctx.fillText(`P${spinner.side}`, 0, spinner.radius * 1.38 + 14);
    ctx.restore();
  }

  /**
   * 发射瞄准射线：细长灯管 + 节点光效 + 小巧箭头，保持呼吸感但不再遮挡桌面。
   */
  private drawAimArrow(spinner: Spinner): void {
    const ctx = this.ctx;
    const color = SIDE_COLORS[spinner.side].main;
    const direction = getAimDirection(spinner.side, spinner.aimOffset);
    const length = this.arenaRadius * 0.52;
    const origin = spinner.pos;
    const dirX = direction.x;
    const dirY = direction.y;
    const perpX = -dirY;
    const perpY = dirX;
    const breathe = (Math.sin(this.screenTime * 3.2 + spinner.side * 1.4) + 1) / 2;
    const startX = origin.x + dirX * spinner.radius * 1.08;
    const startY = origin.y + dirY * spinner.radius * 1.08;
    const endX = origin.x + dirX * length;
    const endY = origin.y + dirY * length;
    const beamWidth = Math.max(1.3, spinner.radius * 0.1);

    ctx.save();
    ctx.lineCap = 'butt';

    // 外层柔光：只保留一条克制的呼吸光带。
    ctx.globalAlpha = 0.045 + breathe * 0.055;
    ctx.strokeStyle = color;
    ctx.lineWidth = beamWidth * (4.4 + breathe * 1.2);
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // 长方形射线主体。
    const beamGradient = ctx.createLinearGradient(startX, startY, endX, endY);
    beamGradient.addColorStop(0, color);
    beamGradient.addColorStop(0.68, color);
    beamGradient.addColorStop(1, '#fff8e6');
    ctx.globalAlpha = 0.38 + breathe * 0.24;
    ctx.strokeStyle = beamGradient;
    ctx.lineWidth = beamWidth;
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // 中心高光让射线看起来像发光灯管。
    ctx.globalAlpha = 0.15 + breathe * 0.16;
    ctx.strokeStyle = '#fff8e6';
    ctx.lineWidth = Math.max(0.8, beamWidth * 0.3);
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // 节点光效：沿射线规律分布的小光点。
    for (let i = 0; i < 4; i += 1) {
      const t = 0.22 + i * 0.17;
      const nodeX = startX + (endX - startX) * t;
      const nodeY = startY + (endY - startY) * t;
      const pulse = (Math.sin(this.screenTime * 4.6 + i * 1.35 + spinner.side) + 1) / 2;
      const nodeRadius = Math.max(1.4, spinner.radius * (0.052 + pulse * 0.018));
      ctx.globalAlpha = 0.3 + pulse * 0.32;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(nodeX, nodeY, nodeRadius, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 0.52 + pulse * 0.4;
      ctx.fillStyle = '#fff8e6';
      ctx.beginPath();
      ctx.arc(nodeX, nodeY, Math.max(0.65, nodeRadius * 0.38), 0, Math.PI * 2);
      ctx.fill();
    }

    // 末端小巧箭头：不遮挡视线，但能明确读出指向。
    const arrowLength = Math.max(5, spinner.radius * 0.34);
    const arrowHalf = Math.max(2, spinner.radius * 0.12);
    const tipX = endX + dirX * arrowLength * 0.16;
    const tipY = endY + dirY * arrowLength * 0.16;
    const baseX = endX - dirX * arrowLength;
    const baseY = endY - dirY * arrowLength;
    const headGradient = ctx.createLinearGradient(baseX, baseY, tipX, tipY);
    headGradient.addColorStop(0, color);
    headGradient.addColorStop(1, '#fff8e6');
    ctx.globalAlpha = 0.72 + breathe * 0.2;
    ctx.fillStyle = headGradient;
    ctx.beginPath();
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(baseX + perpX * arrowHalf, baseY + perpY * arrowHalf);
    ctx.lineTo(baseX - perpX * arrowHalf, baseY - perpY * arrowHalf);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 250, 235, 0.82)';
    ctx.lineWidth = 0.8;
    ctx.stroke();

    // 箭尖的一点呼吸光晕。
    ctx.globalAlpha = 0.1 + breathe * 0.12;
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(endX, endY, arrowLength * 0.9, 0, Math.PI * 2);
    ctx.stroke();

    // 机体与射线衔接处的小光点。
    ctx.globalAlpha = 0.5;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(startX, startY, Math.max(1, spinner.radius * 0.06), 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  private drawImpactFlashes(): void {
    if (this.impactFlashes.length === 0) return;
    const ctx = this.ctx;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const flash of this.impactFlashes) {
      const progress = 1 - flash.life / flash.maxLife;
      const alpha = Math.pow(Math.max(0, 1 - progress), 1.6);
      if (alpha <= 0.001) continue;
      const gradient = ctx.createRadialGradient(
        flash.x,
        flash.y,
        0,
        flash.x,
        flash.y,
        flash.radius,
      );
      gradient.addColorStop(0, 'rgba(255, 255, 255, 0.95)');
      gradient.addColorStop(0.12, 'rgba(255, 255, 255, 0.58)');
      gradient.addColorStop(0.35, 'rgba(255, 243, 208, 0.22)');
      gradient.addColorStop(0.7, 'rgba(255, 198, 132, 0.09)');
      gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.globalAlpha = alpha * 0.85;
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(flash.x, flash.y, flash.radius, 0, Math.PI * 2);
      ctx.fill();

      // 外缘细环：把“爆闪”从一团柔光收成有边界的冲击波。
      ctx.globalAlpha = alpha * 0.42;
      ctx.strokeStyle = flash.color;
      ctx.lineWidth = Math.max(1, flash.radius * 0.018);
      ctx.beginPath();
      ctx.arc(flash.x, flash.y, flash.radius * 0.82, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  /**
   * 碰撞飘字：easeOutBack 的 Q 弹放大 → 上浮 → 淡出。
   * 字体与配色沿用 HUD 的窄体大写 + 金色/青色霓虹描边。
   */
  private drawFloatingTexts(): void {
    if (this.floatingTexts.length === 0) return;
    const ctx = this.ctx;
    // MAX HIT 永远最后绘制：与 COUNTER 同时存在时压在它上面，不会被低优先级飘字遮住。
    const ordered = this.floatingTexts
      .slice()
      .sort((a, b) => Number(a.tone === 'max') - Number(b.tone === 'max'));
    for (const item of ordered) {
      const progress = 1 - item.life / item.maxLife;
      // 起始即保持可读尺寸，随后向上弹一下再回落；顿帧定格时也不会缩成一点。
      const pop = Math.min(1, progress / 0.3);
      const overshoot = Math.sin(pop * Math.PI) * 0.22;
      const settle = (1 - Math.pow(1 - pop, 3)) * 0.06;
      const scale = 1.04 + overshoot - settle;
      const alphaOut = Math.min(1, (1 - progress) / 0.34);
      const alpha = Math.max(0, alphaOut);
      if (alpha <= 0.002) continue;

      const isMax = item.tone === 'max';
      const size = item.size;
      const x = item.x;
      const y = item.y - progress * item.rise;

      ctx.save();
      ctx.translate(x, y);
      ctx.scale(scale, scale);
      ctx.globalAlpha = alpha;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.lineJoin = 'round';

      const fill = ctx.createLinearGradient(0, -size * 0.55, 0, size * 0.55);
      if (isMax) {
        fill.addColorStop(0, '#fffbe2');
        fill.addColorStop(0.42, '#ffd35c');
        fill.addColorStop(1, '#ff7326');
      } else {
        fill.addColorStop(0, '#f4ffff');
        fill.addColorStop(0.46, '#a5f8ff');
        fill.addColorStop(1, '#31c5ff');
      }

      // 深色描边先把文字从战场里“抠”出来，再用霓虹辉光压一层光晕。
      ctx.font = `900 ${size.toFixed(1)}px "Barlow Condensed", "Noto Sans SC", sans-serif`;
      ctx.strokeStyle = isMax ? 'rgba(66, 8, 4, 0.96)' : 'rgba(3, 27, 38, 0.96)';
      ctx.lineWidth = Math.max(3, size * 0.16);
      ctx.shadowColor = isMax ? 'rgba(255, 92, 32, 0.9)' : 'rgba(88, 236, 255, 0.85)';
      ctx.shadowBlur = size * (isMax ? 0.95 : 0.7);
      ctx.strokeText(item.text, 0, 0);
      ctx.fillStyle = fill;
      ctx.fillText(item.text, 0, 0);

      if (item.sub) {
        const subSize = size * 0.33;
        ctx.font = `700 ${subSize.toFixed(1)}px "Barlow Condensed", "Noto Sans SC", sans-serif`;
        ctx.shadowBlur = size * 0.32;
        ctx.globalAlpha = alpha * 0.9;
        ctx.fillStyle = isMax ? '#ffe6a8' : '#d9feff';
        ctx.fillText(item.sub, 0, size * 0.64);
      }
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  }

  private drawShockwaves(): void {
    const ctx = this.ctx;
    ctx.save();
    for (const wave of this.shockwaves) {
      const progress = 1 - wave.life / wave.maxLife;
      ctx.globalAlpha = (1 - progress) * 0.65;
      ctx.strokeStyle = wave.color;
      ctx.lineWidth = 1.4 + (1 - progress) * 1.4;
      ctx.beginPath();
      ctx.arc(wave.x, wave.y, wave.radius, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  private drawResultScene(): void {
    this.drawArena();
    const ctx = this.ctx;
    const draw = this.resultDraw;
    const winnerSide = this.resultWinnerSide;
    const winnerType = this.types[draw ? 0 : winnerSide - 1];
    const color = draw ? '#d8c391' : SIDE_COLORS[winnerSide].main;
    const radius = this.arenaRadius * (draw ? 0.225 : 0.265);
    const x = this.centerX;
    const y = this.centerY;

    const halo = ctx.createRadialGradient(x, y, radius * 0.35, x, y, radius * 2.35);
    halo.addColorStop(0, draw ? 'rgba(216, 195, 145, 0.22)' : winnerType.colors.glow);
    halo.addColorStop(0.4, 'rgba(255, 255, 255, 0.025)');
    halo.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.save();
    ctx.globalAlpha = 0.7;
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(x, y, radius * 2.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    for (let i = 0; i < 3; i += 1) {
      const ringRadius = radius * (1.32 + i * 0.24);
      const alpha = 0.32 - i * 0.07;
      ctx.strokeStyle = i === 0 ? color : 'rgba(228, 216, 187, 0.7)';
      ctx.globalAlpha = alpha;
      ctx.lineWidth = i === 0 ? 1.5 : 0.8;
      ctx.setLineDash(i === 0 ? [] : [2, 9]);
      ctx.beginPath();
      ctx.arc(x, y, ringRadius, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;

    if (draw) {
      // 平局：两枚陀螺并排留在桌上，谁也没有被击碎。
      const spread = radius * 2.5;
      drawGyro(ctx, this.types[0], x - spread / 2, y, radius, {
        rotation: this.screenTime * 0.55,
        spinRatio: 0.9,
        side: 1,
        alpha: 1,
        time: this.screenTime,
      });
      drawGyro(ctx, this.types[1], x + spread / 2, y, radius, {
        rotation: -this.screenTime * 0.5,
        spinRatio: 0.9,
        side: 2,
        alpha: 1,
        time: this.screenTime,
      });
      ctx.strokeStyle = 'rgba(228, 216, 187, 0.18)';
      ctx.lineWidth = 1;
      ctx.setLineDash([2, 8]);
      ctx.beginPath();
      ctx.moveTo(x, y - radius * 1.7);
      ctx.lineTo(x, y + radius * 1.7);
      ctx.stroke();
      ctx.setLineDash([]);
    } else {
      drawGyro(ctx, winnerType, x, y, radius, {
        rotation: this.screenTime * 0.55,
        spinRatio: 0.96,
        side: winnerSide,
        alpha: 1,
        time: this.screenTime,
      });
    }

    for (let i = 0; i < CONFIG.result.orbitCount; i += 1) {
      const speed = 0.22 + (i % 4) * 0.055;
      const angle = this.screenTime * speed + (i / CONFIG.result.orbitCount) * Math.PI * 2;
      const orbit = radius * (1.5 + (i % 3) * 0.32);
      const px = x + Math.cos(angle) * orbit;
      const py = y + Math.sin(angle) * orbit * 0.54;
      const size = 1.2 + (i % 3) * 0.8;
      ctx.globalAlpha = 0.35 + (i % 3) * 0.14;
      ctx.fillStyle =
        i % 2 === 0
          ? color
          : draw
            ? this.types[i % 2].colors.accent
            : winnerType.colors.accent;
      ctx.beginPath();
      ctx.arc(px, py, size, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha *= 0.2;
      ctx.strokeStyle = ctx.fillStyle;
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(px, py);
      ctx.lineTo(
        x + Math.cos(angle - 0.12) * orbit,
        y + Math.sin(angle - 0.12) * orbit * 0.54,
      );
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    ctx.save();
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(239, 228, 203, 0.46)';
    ctx.font = '500 10px "Barlow Condensed", "Noto Sans SC", sans-serif';
    ctx.fillText(
      draw ? 'DRAW / 平局' : `WINNER / ${winnerType.code}`,
      x,
      y - radius * 1.52,
    );
    ctx.restore();
  }
}
