import { CONFIG, randomBetween } from './data';

type ParticleKind = 'dot' | 'spark' | 'mote';

interface Particle {
  active: boolean;
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
  color: string;
  kind: ParticleKind;
  drag: number;
  gravity: number;
  rotation: number;
  spin: number;
}

export interface BurstOptions {
  count: number;
  color: string;
  speedMin: number;
  speedMax: number;
  sizeMin: number;
  sizeMax: number;
  lifeMin: number;
  lifeMax: number;
  kind?: ParticleKind;
  direction?: number;
  spread?: number;
}

/** 固定容量对象池。写满后覆盖最旧粒子，活跃数量永不超出 CONFIG.particles.max（当前 220）。 */
export class ParticleSystem {
  private readonly pool: Particle[] = [];
  private cursor = 0;
  private activeCount = 0;

  constructor() {
    for (let i = 0; i < CONFIG.particles.max; i += 1) {
      this.pool.push({
        active: false,
        x: 0,
        y: 0,
        vx: 0,
        vy: 0,
        life: 0,
        maxLife: 1,
        size: 1,
        color: '#ffffff',
        kind: 'dot',
        drag: 2,
        gravity: 0,
        rotation: 0,
        spin: 0,
      });
    }
  }

  get count(): number {
    return this.activeCount;
  }

  private take(): Particle {
    for (let i = 0; i < this.pool.length; i += 1) {
      const index = (this.cursor + i) % this.pool.length;
      const particle = this.pool[index];
      if (!particle.active) {
        this.cursor = (index + 1) % this.pool.length;
        this.activeCount += 1;
        return particle;
      }
    }
    const particle = this.pool[this.cursor];
    this.cursor = (this.cursor + 1) % this.pool.length;
    return particle;
  }

  clear(): void {
    for (const particle of this.pool) particle.active = false;
    this.cursor = 0;
    this.activeCount = 0;
  }

  burst(x: number, y: number, options: BurstOptions): void {
    const count = Math.min(options.count, CONFIG.particles.max);
    for (let i = 0; i < count; i += 1) {
      const angle =
        options.direction === undefined
          ? Math.random() * Math.PI * 2
          : options.direction + randomBetween(-(options.spread ?? 0.8), options.spread ?? 0.8);
      const speed = randomBetween(options.speedMin, options.speedMax);
      const particle = this.take();
      particle.active = true;
      particle.x = x;
      particle.y = y;
      particle.vx = Math.cos(angle) * speed;
      particle.vy = Math.sin(angle) * speed;
      particle.maxLife = randomBetween(options.lifeMin, options.lifeMax);
      particle.life = particle.maxLife;
      particle.size = randomBetween(options.sizeMin, options.sizeMax);
      particle.color = options.color;
      particle.kind = options.kind ?? 'spark';
      particle.drag = randomBetween(2.8, 4.4);
      particle.gravity = 0;
      particle.rotation = angle;
      particle.spin = randomBetween(-9, 9);
    }
  }

  trail(x: number, y: number, color: string, strength: number): void {
    const particle = this.take();
    particle.active = true;
    particle.x = x + randomBetween(-2, 2);
    particle.y = y + randomBetween(-2, 2);
    particle.vx = randomBetween(-12, 12);
    particle.vy = randomBetween(-12, 12);
    particle.maxLife = randomBetween(0.16, 0.3);
    particle.life = particle.maxLife;
    particle.size = randomBetween(1.1, 2.6) * (0.75 + strength * 0.25);
    particle.color = color;
    particle.kind = 'mote';
    particle.drag = 1;
    particle.gravity = 0;
    particle.rotation = 0;
    particle.spin = 0;
  }

  update(dt: number): void {
    for (const particle of this.pool) {
      if (!particle.active) continue;
      particle.life -= dt;
      if (particle.life <= 0) {
        particle.active = false;
        this.activeCount = Math.max(0, this.activeCount - 1);
        continue;
      }
      const damping = Math.exp(-particle.drag * dt);
      particle.vx *= damping;
      particle.vy *= damping;
      particle.vy += particle.gravity * dt;
      particle.x += particle.vx * dt;
      particle.y += particle.vy * dt;
      particle.rotation += particle.spin * dt;
    }
  }

  draw(ctx: CanvasRenderingContext2D): void {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const particle of this.pool) {
      if (!particle.active) continue;
      const progress = particle.life / particle.maxLife;
      const alpha = Math.min(1, progress * 1.7);
      ctx.globalAlpha = alpha;
      ctx.fillStyle = particle.color;
      if (particle.kind === 'spark') {
        ctx.save();
        ctx.translate(particle.x, particle.y);
        ctx.rotate(particle.rotation);
        ctx.fillRect(
          -particle.size * 2,
          -particle.size * 0.45,
          particle.size * 4,
          particle.size * 0.9,
        );
        ctx.restore();
      } else if (particle.kind === 'mote') {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size * (0.55 + progress * 0.45), 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
  }
}
