import { CONFIG, type ChargeTier } from './data';

type AudioContextCtor = typeof AudioContext;

/**
 * 全部声音均由 Web Audio 实时合成，不依赖外部音频文件。
 * 第一次键盘或指针交互后解锁 AudioContext。
 */
export class AudioEngine {
  private context: AudioContext | null = null;
  private master: GainNode | null = null;
  private sfxBus: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private noiseBuffer: AudioBuffer | null = null;
  private musicTimer: number | null = null;
  private droneNodes: OscillatorNode[] = [];
  private musicStarted = false;
  private musicStep = 0;

  sfxEnabled = true;
  musicEnabled = true;

  async unlock(): Promise<void> {
    if (!this.context) {
      const Ctor: AudioContextCtor | undefined =
        window.AudioContext ??
        (window as unknown as { webkitAudioContext?: AudioContextCtor }).webkitAudioContext;
      if (!Ctor) return;
      this.context = new Ctor();
      this.setupGraph();
    }
    if (this.context.state === 'suspended') {
      try {
        await this.context.resume();
      } catch {
        return;
      }
    }
    if (this.musicEnabled) this.startMusic();
  }

  private setupGraph(): void {
    if (!this.context) return;
    const compressor = this.context.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 16;
    compressor.ratio.value = 8;
    compressor.attack.value = 0.003;
    compressor.release.value = 0.24;

    this.master = this.context.createGain();
    this.master.gain.value = CONFIG.audio.masterVolume;
    this.sfxBus = this.context.createGain();
    this.sfxBus.gain.value = CONFIG.audio.sfxVolume;
    this.musicBus = this.context.createGain();
    this.musicBus.gain.value = CONFIG.audio.musicVolume;

    this.sfxBus.connect(this.master);
    this.musicBus.connect(this.master);
    this.master.connect(compressor);
    compressor.connect(this.context.destination);

    const length = Math.floor(this.context.sampleRate * 0.8);
    const buffer = this.context.createBuffer(1, length, this.context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i += 1) {
      data[i] = Math.random() * 2 - 1;
    }
    this.noiseBuffer = buffer;
  }

  setSfxEnabled(enabled: boolean): void {
    this.sfxEnabled = enabled;
  }

  setMusicEnabled(enabled: boolean): void {
    this.musicEnabled = enabled;
    if (!this.context || !this.musicBus) return;
    const now = this.context.currentTime;
    this.musicBus.gain.cancelScheduledValues(now);
    this.musicBus.gain.setTargetAtTime(
      enabled ? CONFIG.audio.musicVolume : 0,
      now,
      0.08,
    );
    if (enabled) {
      this.startMusic();
    } else {
      this.stopMusic();
    }
  }

  private startMusic(): void {
    if (!this.context || !this.musicBus || this.musicStarted || !this.musicEnabled) return;
    this.musicStarted = true;
    this.musicBus.gain.setTargetAtTime(CONFIG.audio.musicVolume, this.context.currentTime, 0.4);

    const now = this.context.currentTime;
    const filter = this.context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 230;
    filter.Q.value = 0.7;
    filter.connect(this.musicBus);

    [73.42, 110, 146.83].forEach((frequency, index) => {
      if (!this.context) return;
      const oscillator = this.context.createOscillator();
      const gain = this.context.createGain();
      oscillator.type = index === 0 ? 'sine' : 'triangle';
      oscillator.frequency.value = frequency;
      gain.gain.value = index === 0 ? 0.055 : 0.012;
      oscillator.connect(gain);
      gain.connect(filter);
      oscillator.start(now);
      this.droneNodes.push(oscillator);
    });

    this.scheduleMusicBar();
    this.musicTimer = window.setInterval(() => this.scheduleMusicBar(), 2600);
  }

  private stopMusic(): void {
    if (this.musicTimer !== null) {
      window.clearInterval(this.musicTimer);
      this.musicTimer = null;
    }
    for (const node of this.droneNodes) {
      try {
        node.stop();
      } catch {
        // 已停止的振荡器忽略即可。
      }
    }
    this.droneNodes = [];
    this.musicStarted = false;
  }

  private scheduleMusicBar(): void {
    if (!this.context || !this.musicEnabled || !this.musicBus) return;
    const scale = [146.83, 174.61, 196, 220, 261.63, 293.66];
    const pattern = [0, 4, 2, 3, 1, 5, 3, 2];
    const start = this.context.currentTime + 0.05;
    const base = this.musicStep % 2 === 0 ? 1 : 0.5;
    for (let i = 0; i < 4; i += 1) {
      const note = scale[pattern[(this.musicStep + i) % pattern.length]];
      this.pluck(note * base, start + i * 0.61, 0.09, 0.012);
    }
    if (this.musicStep % 4 === 0) {
      this.musicNoiseSwell(start, 2.1);
    }
    this.musicStep += 1;
  }

  private pluck(frequency: number, at: number, decay: number, volume: number): void {
    if (!this.context || !this.musicBus) return;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    const filter = this.context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 540;
    oscillator.type = 'triangle';
    oscillator.frequency.value = frequency;
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.exponentialRampToValueAtTime(volume, at + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, at + decay);
    oscillator.connect(filter);
    filter.connect(gain);
    gain.connect(this.musicBus);
    oscillator.start(at);
    oscillator.stop(at + decay + 0.05);
  }

  private musicNoiseSwell(at: number, duration: number): void {
    if (!this.context || !this.musicBus || !this.noiseBuffer) return;
    const source = this.context.createBufferSource();
    const filter = this.context.createBiquadFilter();
    const gain = this.context.createGain();
    source.buffer = this.noiseBuffer;
    source.loop = true;
    filter.type = 'bandpass';
    filter.frequency.value = 420;
    filter.Q.value = 0.8;
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.linearRampToValueAtTime(0.006, at + duration * 0.45);
    gain.gain.linearRampToValueAtTime(0.0001, at + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.musicBus);
    source.start(at);
    source.stop(at + duration + 0.05);
  }

  private tone(
    frequency: number,
    duration: number,
    type: OscillatorType,
    volume: number,
    frequencyEnd?: number,
    delay = 0,
  ): void {
    if (!this.context || !this.sfxBus || !this.sfxEnabled) return;
    const at = this.context.currentTime + delay;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(frequency, at);
    if (frequencyEnd !== undefined) {
      oscillator.frequency.exponentialRampToValueAtTime(
        Math.max(20, frequencyEnd),
        at + duration,
      );
    }
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.exponentialRampToValueAtTime(volume, at + 0.006);
    gain.gain.exponentialRampToValueAtTime(0.0001, at + duration);
    oscillator.connect(gain);
    gain.connect(this.sfxBus);
    oscillator.start(at);
    oscillator.stop(at + duration + 0.02);
  }

  private noise(
    duration: number,
    volume: number,
    filterType: BiquadFilterType,
    frequency: number,
    delay = 0,
  ): void {
    if (!this.context || !this.sfxBus || !this.noiseBuffer || !this.sfxEnabled) return;
    const at = this.context.currentTime + delay;
    const source = this.context.createBufferSource();
    const filter = this.context.createBiquadFilter();
    const gain = this.context.createGain();
    source.buffer = this.noiseBuffer;
    filter.type = filterType;
    filter.frequency.setValueAtTime(frequency, at);
    filter.frequency.exponentialRampToValueAtTime(Math.max(60, frequency * 0.32), at + duration);
    filter.Q.value = 1.1;
    gain.gain.setValueAtTime(volume, at);
    gain.gain.exponentialRampToValueAtTime(0.0001, at + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.sfxBus);
    source.start(at);
    source.stop(at + duration + 0.02);
  }

  /** 带通噪声扫频：用于破空、摩擦、碎裂这类“气流感”声音。 */
  private sweptNoise(
    duration: number,
    volume: number,
    from: number,
    to: number,
    delay = 0,
    q = 1.1,
  ): void {
    if (!this.context || !this.sfxBus || !this.noiseBuffer || !this.sfxEnabled) return;
    const at = this.context.currentTime + delay;
    const source = this.context.createBufferSource();
    const filter = this.context.createBiquadFilter();
    const gain = this.context.createGain();
    source.buffer = this.noiseBuffer;
    source.loop = true;
    filter.type = 'bandpass';
    filter.Q.value = q;
    filter.frequency.setValueAtTime(from, at);
    filter.frequency.exponentialRampToValueAtTime(Math.max(60, to), at + duration);
    gain.gain.setValueAtTime(0.0001, at);
    gain.gain.exponentialRampToValueAtTime(volume, at + duration * 0.16);
    gain.gain.exponentialRampToValueAtTime(0.0001, at + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.sfxBus);
    source.start(at);
    source.stop(at + duration + 0.05);
  }

  playSelect(): void {
    this.tone(620, 0.06, 'sine', 0.045, 760);
  }

  playConfirm(): void {
    this.tone(310, 0.12, 'triangle', 0.07, 380);
    this.tone(620, 0.18, 'sine', 0.045, 760, 0.045);
  }

  playCountdown(last: boolean): void {
    this.tone(last ? 520 : 380, last ? 0.18 : 0.1, 'square', last ? 0.05 : 0.032);
    if (last) this.tone(780, 0.18, 'sine', 0.03);
  }

  playGo(): void {
    this.tone(260, 0.28, 'triangle', 0.08, 520);
    this.tone(520, 0.42, 'sine', 0.05, 1040);
    this.noise(0.18, 0.045, 'highpass', 1200);
  }

  playLaunch(power: number): void {
    const base = 140 + power * 150;
    this.noise(0.3, 0.05 + power * 0.035, 'bandpass', 380 + power * 520);
    this.tone(base, 0.24, 'sawtooth', 0.035, base * 2.2);
  }

  /** 发射入场：高频破空声快速滑落，P2 略微延后，形成两道错开的入场。 */
  playLaunchWhoosh(side: 1 | 2 = 1): void {
    const delay = side === 2 ? 0.055 : 0;
    this.sweptNoise(0.46, 0.058, 3200, 360, delay, 1.6);
    this.tone(760, 0.34, 'sawtooth', 0.02, 180, delay);
    this.tone(1180, 0.24, 'sine', 0.014, 420, delay + 0.012);
  }

  /** 入场落地：金属压上桌面的短促闷响 + 气浪收束。 */
  playEntryLanding(power: number): void {
    const clamped = Math.max(0, Math.min(1, power));
    this.tone(96 + clamped * 42, 0.3, 'sine', 0.085 + clamped * 0.05, 44);
    this.tone(330 + clamped * 180, 0.16, 'triangle', 0.028, 150);
    this.noise(0.24, 0.05 + clamped * 0.03, 'lowpass', 720);
    this.sweptNoise(0.36, 0.048, 5200, 880, 0, 0.9);
  }

  /** MAX 满力撞击专用顿帧音：最沉重的低频冲击核 + 金属爆裂 + 长尾余响。 */
  playHitStop(force = 1): void {
    const clamped = Math.max(0, Math.min(1, force));
    this.tone(44 + clamped * 12, 0.44, 'sine', 0.15 + clamped * 0.05, 24);
    this.tone(88 + clamped * 26, 0.26, 'triangle', 0.058 + clamped * 0.028, 32);
    this.noise(0.16, 0.105 + clamped * 0.04, 'lowpass', 900);
    this.sweptNoise(0.3, 0.075, 7200, 620, 0, 1.15);
    this.tone(2100, 0.09, 'square', 0.016, 420);
  }

  /** 碰撞后脱离：短促的金属摩擦。 */
  playScrape(intensity: number): void {
    const clamped = Math.max(0, Math.min(1, intensity));
    const delay = 0.04 + Math.random() * 0.06;
    this.sweptNoise(0.15 + clamped * 0.13, 0.016 + clamped * 0.03, 4400, 900, delay, 0.9);
    this.tone(520 + clamped * 320, 0.13, 'triangle', 0.011 + clamped * 0.012, 210, delay);
  }

  /** 战败方碎裂：金属崩解 + 碎片散落。 */
  playShatter(): void {
    this.sweptNoise(0.5, 0.075, 5200, 240, 0, 0.7);
    this.tone(168, 0.5, 'sawtooth', 0.055, 48);
    this.tone(93, 0.72, 'sine', 0.06, 34, 0.04);
    for (let i = 0; i < 3; i += 1) {
      this.tone(1400 + i * 620, 0.12, 'square', 0.012, 300, 0.08 + i * 0.07);
    }
  }

  /** 平局收场：两个音高谁也不压过谁，最后一起落下。 */
  playDraw(): void {
    this.tone(392, 0.5, 'triangle', 0.048, 392);
    this.tone(293.66, 0.7, 'sine', 0.042, 293.66, 0.12);
    this.tone(196, 0.92, 'sine', 0.05, 196, 0.24);
  }

  /** 冲刺释放：短促的气流爆音 + 上升金属啸叫。 */
  playDash(power: number): void {
    const clamped = Math.max(0, Math.min(1, power));
    this.sweptNoise(0.28, 0.04 + clamped * 0.035, 2200, 520, 0, 1.4);
    this.tone(220 + clamped * 180, 0.24, 'sawtooth', 0.026 + clamped * 0.02, 760 + clamped * 420);
    this.tone(980 + clamped * 520, 0.16, 'sine', 0.012, 420, 0.03);
  }

  /** 冲刺命中：低频冲击 + 高频金属撕裂。 */
  playDashImpact(power: number, intensity: number): void {
    const clamped = Math.max(0, Math.min(1, power));
    const force = Math.max(0, Math.min(1, intensity));
    this.tone(72 + clamped * 34, 0.3, 'sine', 0.06 + clamped * 0.045, 38);
    this.tone(160 + clamped * 90, 0.2, 'sawtooth', 0.03 + clamped * 0.025, 54);
    this.sweptNoise(0.22, 0.045 + force * 0.03, 5400, 720, 0, 0.8);
  }

  playHit(intensity: number, heavy: boolean, tier: ChargeTier): void {
    const clamped = Math.max(0, Math.min(1, intensity));
    const volume = 0.055 + clamped * 0.075;
    this.tone(180 + clamped * 260, 0.11 + clamped * 0.06, 'triangle', volume, 90);
    this.tone(920 + clamped * 580, 0.09, 'sine', 0.022 + clamped * 0.025, 520);
    this.noise(0.08 + clamped * 0.05, 0.03 + clamped * 0.045, 'bandpass', 1800);

    if (tier === 'red' || tier === 'max') {
      this.tone(tier === 'max' ? 92 : 120, 0.22, 'sine', heavy ? 0.1 : 0.07, 52);
      this.tone(tier === 'max' ? 1480 : 1120, 0.13, 'triangle', 0.03, 680);
      this.noise(0.16, 0.06, 'highpass', 2400);
    }
  }

  playWall(penalty: boolean): void {
    this.tone(penalty ? 74 : 110, penalty ? 0.34 : 0.18, 'sine', penalty ? 0.13 : 0.07, 42);
    this.noise(penalty ? 0.32 : 0.16, penalty ? 0.085 : 0.045, 'lowpass', 520);
    if (penalty) {
      this.tone(170, 0.32, 'sawtooth', 0.045, 60);
      this.tone(240, 0.28, 'sine', 0.03, 80, 0.08);
    }
  }

  playOut(): void {
    this.tone(220, 0.8, 'sawtooth', 0.07, 38);
    this.tone(110, 1.1, 'sine', 0.09, 28);
    this.noise(0.7, 0.07, 'lowpass', 460);
  }

  playWin(): void {
    const notes = [261.63, 329.63, 392, 523.25];
    notes.forEach((note, index) => {
      this.tone(note, 0.8, 'triangle', 0.055, note * 1.002, index * 0.12);
    });
    this.tone(65.41, 1.5, 'sine', 0.06, 65.41);
  }
}
