import {
  CONFIG,
  getMass,
  getMaxRpm,
  getTier,
  type ChargeTier,
  type GyroType,
  type Vec2,
} from './data';

export interface SpinnerOptions {
  side: 1 | 2;
  type: GyroType;
  x: number;
  y: number;
  radius: number;
}

export interface DrawGyroOptions {
  rotation: number;
  spinRatio?: number;
  side?: 1 | 2;
  tier?: ChargeTier;
  locked?: boolean;
  hitFlash?: number;
  alpha?: number;
  time?: number;
}

export class Spinner {
  readonly side: 1 | 2;
  readonly type: GyroType;
  radius: number;
  readonly mass: number;
  readonly maxRpm: number;
  /** 血量上限：初始总转速 */
  readonly maxSpin: number;

  pos: Vec2;
  vel: Vec2 = { x: 0, y: 0 };
  aimOffset = 0;
  aimVelocity = 0;
  visualAngle = Math.random() * Math.PI * 2;
  spin: number;
  charge = 0;
  tier: ChargeTier = 'under';
  chargeLocked = false;
  private previousChargeHeld = false;
  launched = false;
  hasHit = false;
  chargeBonusUsed = false;
  maxWallPenaltyUsed = false;
  /**
   * 发射瞬间是否达到 MAX 满力。
   * 一旦发射就固定下来，不会被倒计时结束后的蓄力清零 / 实时 tier 变化改写。
   * 首次真实碰撞后清空，避免同一次发射反复触发 MAX 表现。
   */
  wasMaxHit = false;
  /**
   * 本次冲刺松开时是否蓄满 MAX。
   * 每次满力冲刺命中一次后清空；冲刺窗口结束仍未命中也会清空，避免残留到下一次普通碰撞。
   */
  dashWasMaxHit = false;
  out = false;
  outReason: 'stop' | 'ring' | null = null;
  hitFlash = 0;
  trailTimer = 0;
  hitCount = 0;
  launchSpinBoost = 0;

  /** 局内冲刺状态 */
  dashCharge = 0;
  dashCharging = false;
  dashCooldown = 0;
  dashActive = 0;
  dashPower = 0;
  dashHeld = false;
  dashInterrupted = false;
  dashBreakFlash = 0;
  /** 破招后的强制蓄力封锁剩余时间（秒）。 */
  dashLockout = 0;
  /** MAX 满力闪电的火花计时。 */
  sparkTimer = 0;
  /**
   * 无输入时的转子微震：上一帧叠加到 pos 上的抖动位移。
   * 下一帧物理推进前会先扣回，保证抖动只在原地晃动，不会累积成真实漂移。
   */
  idleWobble: Vec2 = { x: 0, y: 0 };
  /** 微震相位：每枚陀螺随机起点，双轴频率不成整数比，避免出现规律轨迹。 */
  idlePhase = Math.random() * Math.PI * 2;
  /** 松开走位后的惯性滑行剩余时间（秒）。 */
  coastTimer = 0;

  constructor(options: SpinnerOptions) {
    this.side = options.side;
    this.type = options.type;
    this.pos = { x: options.x, y: options.y };
    this.radius = options.radius;
    this.mass = getMass(options.type);
    this.maxRpm = getMaxRpm(options.type);
    this.maxSpin = CONFIG.spinner.maxSpin;
    this.spin = this.maxSpin;
  }

  get spinRatio(): number {
    return Math.max(0, Math.min(1, this.spin / this.maxSpin));
  }

  get rpm(): number {
    return Math.round(this.spinRatio * this.maxRpm);
  }

  get isAlive(): boolean {
    return !this.out;
  }

  resetCharge(): void {
    this.charge = 0;
    this.tier = 'under';
    this.chargeLocked = false;
    this.previousChargeHeld = false;
    this.wasMaxHit = false;
    this.dashWasMaxHit = false;
    // 每一轮开始都清空上一轮遗留的破招封锁与闪电状态。
    this.dashLockout = 0;
    this.sparkTimer = 0;
    this.idleWobble.x = 0;
    this.idleWobble.y = 0;
    this.coastTimer = 0;
  }

  /** 按住蓄力，松开锁定当前档位；再次按下可继续蓄力。 */
  updateCharge(holding: boolean, dt: number): void {
    if (holding && !this.previousChargeHeld) this.chargeLocked = false;
    if (!holding && this.previousChargeHeld) this.chargeLocked = true;

    if (holding) {
      this.charge = Math.min(1, this.charge + dt / CONFIG.charge.duration);
    }
    this.previousChargeHeld = holding;
    this.tier = getTier(this.charge);
  }

  updateAim(delta: -1 | 0 | 1, dt: number): void {
    this.aimVelocity += delta * CONFIG.aim.acceleration * dt;
    this.aimVelocity *= Math.exp(-CONFIG.aim.damping * dt);
    this.aimVelocity = Math.max(
      -CONFIG.aim.maxSpeed,
      Math.min(CONFIG.aim.maxSpeed, this.aimVelocity),
    );
    this.aimOffset += this.aimVelocity * dt;
    if (this.aimOffset > CONFIG.aim.limit) {
      this.aimOffset = CONFIG.aim.limit;
      this.aimVelocity *= CONFIG.aim.clampRebound;
    } else if (this.aimOffset < -CONFIG.aim.limit) {
      this.aimOffset = -CONFIG.aim.limit;
      this.aimVelocity *= CONFIG.aim.clampRebound;
    }
  }

  updateVisual(dt: number): void {
    this.launchSpinBoost = Math.max(0, this.launchSpinBoost - dt * 5);
    const speed = (5.5 + this.spinRatio * 31 + this.launchSpinBoost) * (this.out ? 0.2 : 1);
    this.visualAngle += speed * dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt * 3.6);
    this.dashBreakFlash = Math.max(0, this.dashBreakFlash - dt * 2.8);
  }

  get visualSpin(): number {
    return 5.5 + this.spinRatio * 31 + this.launchSpinBoost;
  }

  draw(ctx: CanvasRenderingContext2D, time: number, alpha = 1): void {
    drawGyro(ctx, this.type, this.pos.x, this.pos.y, this.radius, {
      rotation: this.visualAngle,
      spinRatio: this.spinRatio,
      side: this.side,
      tier: this.tier,
      locked: this.chargeLocked,
      hitFlash: this.hitFlash,
      alpha: alpha * (this.out ? 0.45 : 1),
      time,
    });
  }
}

function drawPattern(
  ctx: CanvasRenderingContext2D,
  type: GyroType,
  radius: number,
): void {
  const accent = type.colors.accent;
  const dark = type.colors.dark;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  if (type.pattern === 'axis') {
    ctx.strokeStyle = 'rgba(36, 34, 26, 0.52)';
    ctx.lineWidth = Math.max(1, radius * 0.055);
    for (let i = 0; i < 3; i += 1) {
      const start = i * ((Math.PI * 2) / 3) + 0.22;
      ctx.beginPath();
      ctx.arc(0, 0, radius * (0.58 + i * 0.055), start, start + 1.13);
      ctx.stroke();
    }
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.75;
    ctx.lineWidth = Math.max(0.8, radius * 0.022);
    for (let i = 0; i < 6; i += 1) {
      const angle = i * (Math.PI / 3) + 0.25;
      ctx.beginPath();
      ctx.arc(
        Math.cos(angle) * radius * 0.43,
        Math.sin(angle) * radius * 0.43,
        radius * 0.035,
        0,
        Math.PI * 2,
      );
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  } else if (type.pattern === 'blade') {
    ctx.fillStyle = 'rgba(35, 8, 6, 0.58)';
    for (let i = 0; i < 3; i += 1) {
      ctx.save();
      ctx.rotate(i * ((Math.PI * 2) / 3));
      ctx.beginPath();
      ctx.moveTo(radius * 0.22, -radius * 0.08);
      ctx.lineTo(radius * 0.92, -radius * 0.28);
      ctx.lineTo(radius * 0.68, radius * 0.12);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.9;
    ctx.lineWidth = Math.max(1, radius * 0.035);
    for (let i = 0; i < 3; i += 1) {
      ctx.save();
      ctx.rotate(i * ((Math.PI * 2) / 3) + 0.5);
      ctx.beginPath();
      ctx.moveTo(radius * 0.3, 0);
      ctx.lineTo(radius * 0.74, 0);
      ctx.stroke();
      ctx.restore();
    }
    ctx.globalAlpha = 1;
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.3, 0, Math.PI * 2);
    ctx.fill();
  } else if (type.pattern === 'ring') {
    ctx.strokeStyle = 'rgba(10, 28, 39, 0.78)';
    ctx.lineWidth = Math.max(2, radius * 0.13);
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.68, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = type.colors.light;
    ctx.globalAlpha = 0.62;
    ctx.lineWidth = Math.max(0.8, radius * 0.021);
    ctx.beginPath();
    ctx.arc(0, 0, radius * 0.57, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.9;
    for (let i = 0; i < 8; i += 1) {
      const a = i * (Math.PI / 4);
      ctx.beginPath();
      ctx.arc(
        Math.cos(a) * radius * 0.68,
        Math.sin(a) * radius * 0.68,
        radius * 0.045,
        0,
        Math.PI * 2,
      );
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  } else if (type.pattern === 'spiral') {
    ctx.strokeStyle = 'rgba(20, 52, 35, 0.68)';
    ctx.lineWidth = Math.max(1, radius * 0.045);
    for (let i = 0; i < 4; i += 1) {
      const start = i * (Math.PI / 2) + 0.3;
      ctx.beginPath();
      ctx.arc(0, 0, radius * (0.25 + i * 0.14), start, start + 1.56);
      ctx.stroke();
    }
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.8;
    ctx.lineWidth = Math.max(0.8, radius * 0.02);
    for (let i = 0; i < 4; i += 1) {
      const start = i * (Math.PI / 2) + 1.16;
      ctx.beginPath();
      ctx.arc(0, 0, radius * (0.32 + i * 0.135), start, start + 0.66);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  } else {
    ctx.strokeStyle = 'rgba(49, 33, 5, 0.55)';
    ctx.lineWidth = Math.max(0.65, radius * 0.016);
    for (let i = 0; i < 18; i += 1) {
      const a = i * ((Math.PI * 2) / 18);
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * radius * 0.39, Math.sin(a) * radius * 0.39);
      ctx.lineTo(Math.cos(a) * radius * 0.9, Math.sin(a) * radius * 0.9);
      ctx.stroke();
    }
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.9;
    ctx.lineWidth = Math.max(1, radius * 0.038);
    for (let i = 0; i < 3; i += 1) {
      const a = i * ((Math.PI * 2) / 3) + 0.2;
      ctx.beginPath();
      ctx.arc(0, 0, radius * 0.7, a, a + 0.58);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }
}

/** 每种机体一套齿形参数：齿数越少越凶，齿深越大越锋利。 */
function getRimProfile(type: GyroType): { teeth: number; depth: number } {
  switch (type.pattern) {
    case 'blade':
      return { teeth: 9, depth: 0.09 };
    case 'ring':
      return { teeth: 22, depth: 0.035 };
    case 'spiral':
      return { teeth: 14, depth: 0.06 };
    case 'comet':
      return { teeth: 7, depth: 0.11 };
    default:
      return { teeth: 12, depth: 0.05 };
  }
}

/** 程序化绘制一枚俯视陀螺，不依赖图片资源。 */
export function drawGyro(
  ctx: CanvasRenderingContext2D,
  type: GyroType,
  x: number,
  y: number,
  radius: number,
  options: DrawGyroOptions,
): void {
  const rotation = options.rotation;
  const spinRatio = Math.max(0, Math.min(1, options.spinRatio ?? 1));
  const alpha = options.alpha ?? 1;
  const time = options.time ?? 0;
  const hitFlash = options.hitFlash ?? 0;
  const tier = options.tier ?? 'under';
  const sideColor = options.side === 1 ? '#67e8c6' : '#ff8059';

  ctx.save();
  ctx.globalAlpha = alpha;

  // 环境辉光：让陀螺在深色桌面上浮起来，转速越高越亮。
  if (spinRatio > 0.04) {
    const aura = ctx.createRadialGradient(x, y, radius * 0.25, x, y, radius * 1.95);
    aura.addColorStop(0, type.colors.glow);
    aura.addColorStop(0.5, 'rgba(0, 0, 0, 0)');
    aura.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.globalAlpha = alpha * (0.12 + spinRatio * 0.3);
    ctx.fillStyle = aura;
    ctx.beginPath();
    ctx.arc(x, y, radius * 1.95, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = alpha;
  }

  // 桌面投影：用径向渐变代替大范围阴影，开销更低。
  const shadow = ctx.createRadialGradient(
    x + radius * 0.18,
    y + radius * 0.28,
    radius * 0.15,
    x + radius * 0.18,
    y + radius * 0.28,
    radius * 1.45,
  );
  shadow.addColorStop(0, 'rgba(0, 0, 0, 0.54)');
  shadow.addColorStop(0.55, 'rgba(0, 0, 0, 0.25)');
  shadow.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.fillStyle = shadow;
  ctx.beginPath();
  ctx.ellipse(x + radius * 0.16, y + radius * 0.28, radius * 1.3, radius * 1.05, 0, 0, Math.PI * 2);
  ctx.fill();

  if (options.side) {
    ctx.strokeStyle = sideColor;
    ctx.globalAlpha = alpha * 0.36;
    ctx.lineWidth = Math.max(1, radius * 0.05);
    ctx.beginPath();
    ctx.arc(x, y, radius + radius * 0.17, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = alpha;
  }

  if (tier !== 'under') {
    const strong = tier === 'max';
    const pulse = 0.55 + Math.sin(time * (strong ? 9 : 5.5)) * 0.2;
    ctx.strokeStyle = strong ? '#ff4654' : '#ff9461';
    ctx.globalAlpha = alpha * (strong ? 0.7 : 0.46) * pulse;
    ctx.lineWidth = Math.max(1.2, radius * (strong ? 0.09 : 0.06));
    ctx.beginPath();
    ctx.arc(x, y, radius + radius * (strong ? 0.32 : 0.22), 0, Math.PI * 2);
    ctx.stroke();
    if (options.locked) {
      ctx.globalAlpha = alpha * 0.8;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(x, y, radius + radius * 0.32, -0.35, 0.35);
      ctx.stroke();
    }
  }

  // 旋转残影：高转速时在陀螺外侧留下拖尾弧线。
  if (spinRatio > 0.3) {
    for (let i = 1; i <= 2; i += 1) {
      ctx.globalAlpha = alpha * spinRatio * (0.16 / i);
      ctx.strokeStyle = i === 1 ? type.colors.accent : type.colors.light;
      ctx.lineWidth = Math.max(0.8, radius * (0.045 - i * 0.012));
      ctx.beginPath();
      ctx.arc(
        x,
        y,
        radius * (0.94 - i * 0.035),
        rotation - i * 0.34,
        rotation - i * 0.06,
      );
      ctx.stroke();
    }
    ctx.globalAlpha = alpha;
  }

  if (spinRatio > 0.55) {
    ctx.globalAlpha = alpha * (spinRatio - 0.55) * 0.5;
    ctx.strokeStyle = type.colors.accent;
    ctx.lineWidth = Math.max(0.8, radius * 0.025);
    for (let i = 0; i < 3; i += 1) {
      const start = rotation - 0.55 - i * 0.42;
      ctx.beginPath();
      ctx.arc(x, y, radius * (0.78 + i * 0.075), start, start + 0.55 + spinRatio * 0.5);
      ctx.stroke();
    }
    ctx.globalAlpha = alpha;
  }

  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rotation);

  // 锋利锯齿轮缘：五种机体各自拥有不同的齿数与齿深，形成机械切割感的外轮廓。
  const rim = getRimProfile(type);
  const bodyRadius = radius * 0.93;
  const tipRadius = radius * 1.07;
  const valleyRadius = Math.max(bodyRadius * 1.01, tipRadius - radius * rim.depth);
  const toothCount = rim.teeth;

  const toothGradient = ctx.createLinearGradient(-radius, -radius, radius, radius);
  toothGradient.addColorStop(0, type.colors.light);
  toothGradient.addColorStop(0.34, type.colors.body);
  toothGradient.addColorStop(0.74, type.colors.dark);
  toothGradient.addColorStop(1, '#070906');

  ctx.beginPath();
  for (let i = 0; i < toothCount * 2; i += 1) {
    const a = (i / (toothCount * 2)) * Math.PI * 2 + 0.12;
    const toothRadius = i % 2 === 0 ? tipRadius : valleyRadius;
    const px = Math.cos(a) * toothRadius;
    const py = Math.sin(a) * toothRadius;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fillStyle = toothGradient;
  ctx.fill();
  ctx.strokeStyle = 'rgba(7, 9, 7, 0.86)';
  ctx.lineWidth = Math.max(0.7, radius * 0.013);
  ctx.stroke();

  // 齿尖受光：每颗齿朝光的一侧压一条亮边，强化“磨过”的金属刃口。
  ctx.globalAlpha = alpha * (0.3 + spinRatio * 0.25);
  ctx.strokeStyle = 'rgba(255, 250, 232, 0.85)';
  ctx.lineWidth = Math.max(0.6, radius * 0.01);
  for (let i = 0; i < toothCount; i += 1) {
    const a = (i / toothCount) * Math.PI * 2 + 0.12;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * tipRadius, Math.sin(a) * tipRadius);
    ctx.lineTo(
      Math.cos(a + 0.09) * (valleyRadius + radius * 0.02),
      Math.sin(a + 0.09) * (valleyRadius + radius * 0.02),
    );
    ctx.stroke();
  }
  ctx.globalAlpha = alpha;

  // 齿根压暗：把锯齿外缘与盘面分层，避免细节糊成一圈。
  ctx.strokeStyle = 'rgba(8, 10, 9, 0.62)';
  ctx.lineWidth = Math.max(0.8, radius * 0.018);
  ctx.beginPath();
  ctx.arc(0, 0, bodyRadius * 1.005, 0, Math.PI * 2);
  ctx.stroke();

  // 外圈金属斜面
  const bodyGradient = ctx.createRadialGradient(
    -radius * 0.36,
    -radius * 0.4,
    radius * 0.06,
    0,
    0,
    bodyRadius,
  );
  bodyGradient.addColorStop(0, type.colors.light);
  bodyGradient.addColorStop(0.38, type.colors.body);
  bodyGradient.addColorStop(0.82, type.colors.dark);
  bodyGradient.addColorStop(1, '#0c0e0c');
  ctx.fillStyle = bodyGradient;
  ctx.beginPath();
  ctx.arc(0, 0, bodyRadius, 0, Math.PI * 2);
  ctx.fill();

  // 外圈金属斜面：外描边 + 受光高光 + 暗面压边，比单圈描边更有体积感。
  ctx.strokeStyle = 'rgba(246, 236, 210, 0.3)';
  ctx.lineWidth = Math.max(0.8, radius * 0.028);
  ctx.beginPath();
  ctx.arc(0, 0, bodyRadius * 0.985, 0, Math.PI * 2);
  ctx.stroke();

  ctx.globalAlpha = alpha * 0.55;
  ctx.strokeStyle = 'rgba(255, 250, 236, 0.9)';
  ctx.lineWidth = Math.max(1, radius * 0.026);
  ctx.beginPath();
  ctx.arc(0, 0, bodyRadius * 0.99, -2.55, -1.15);
  ctx.stroke();

  ctx.globalAlpha = alpha * 0.4;
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.85)';
  ctx.beginPath();
  ctx.arc(0, 0, bodyRadius * 0.99, 0.68, 1.92);
  ctx.stroke();

  // 轮缘强调弧：带上机体主色，旋转时形成一圈细碎高光。
  ctx.globalAlpha = alpha * (0.22 + spinRatio * 0.4);
  ctx.strokeStyle = type.colors.accent;
  ctx.lineWidth = Math.max(1, radius * 0.018);
  for (let i = 0; i < 3; i += 1) {
    const start = i * ((Math.PI * 2) / 3) + 0.34;
    ctx.beginPath();
    ctx.arc(0, 0, bodyRadius * 0.94, start, start + 0.5);
    ctx.stroke();
  }
  ctx.globalAlpha = alpha;

  ctx.save();
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.9, 0, Math.PI * 2);
  ctx.clip();
  drawPattern(ctx, type, radius);

  // 顶部柔光
  const sheen = ctx.createLinearGradient(-radius, -radius, radius, radius);
  sheen.addColorStop(0, 'rgba(255, 255, 255, 0.3)');
  sheen.addColorStop(0.34, 'rgba(255, 255, 255, 0.05)');
  sheen.addColorStop(1, 'rgba(0, 0, 0, 0.16)');
  ctx.fillStyle = sheen;
  ctx.fillRect(-radius, -radius, radius * 2, radius * 2);
  ctx.restore();

  // 轮缘配重铆钉：旋转时提供明确的机械细节。
  for (let i = 0; i < 6; i += 1) {
    const angle = i * (Math.PI / 3) + Math.PI / 12;
    const rx = Math.cos(angle) * radius * 0.845;
    const ry = Math.sin(angle) * radius * 0.845;
    ctx.fillStyle = 'rgba(12, 14, 11, 0.82)';
    ctx.beginPath();
    ctx.arc(rx, ry, Math.max(1.2, radius * 0.045), 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = type.colors.light;
    ctx.globalAlpha = alpha * 0.72;
    ctx.beginPath();
    ctx.arc(
      rx - radius * 0.012,
      ry - radius * 0.012,
      Math.max(0.6, radius * 0.016),
      0,
      Math.PI * 2,
    );
    ctx.fill();
    ctx.globalAlpha = alpha;
  }

  // 内环与中心轴
  ctx.strokeStyle = 'rgba(8, 10, 9, 0.76)';
  ctx.lineWidth = Math.max(1.2, radius * 0.06);
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.31, 0, Math.PI * 2);
  ctx.stroke();

  const hub = ctx.createRadialGradient(
    -radius * 0.08,
    -radius * 0.1,
    radius * 0.02,
    0,
    0,
    radius * 0.27,
  );
  hub.addColorStop(0, '#fff8e5');
  hub.addColorStop(0.36, type.colors.light);
  hub.addColorStop(0.75, type.colors.body);
  hub.addColorStop(1, type.colors.dark);
  ctx.fillStyle = hub;
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.26, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.48)';
  ctx.lineWidth = Math.max(0.6, radius * 0.016);
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.245, 0, Math.PI * 2);
  ctx.stroke();

  // 轴心十字与主色环
  ctx.strokeStyle = 'rgba(20, 22, 18, 0.55)';
  ctx.lineWidth = Math.max(0.7, radius * 0.014);
  ctx.beginPath();
  ctx.moveTo(-radius * 0.17, 0);
  ctx.lineTo(radius * 0.17, 0);
  ctx.moveTo(0, -radius * 0.17);
  ctx.lineTo(0, radius * 0.17);
  ctx.stroke();

  ctx.strokeStyle = type.colors.accent;
  ctx.globalAlpha = alpha * 0.7;
  ctx.lineWidth = Math.max(0.7, radius * 0.012);
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.155, 0, Math.PI * 2);
  ctx.stroke();
  ctx.globalAlpha = alpha;

  ctx.fillStyle = type.colors.dark;
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.055, 0, Math.PI * 2);
  ctx.fill();

  // 旋转指示线：高转速时降低辨识度，形成自然拖影感。
  ctx.globalAlpha = alpha * (1 - spinRatio * 0.58);
  ctx.strokeStyle = type.colors.accent;
  ctx.lineWidth = Math.max(0.8, radius * 0.04);
  ctx.beginPath();
  ctx.moveTo(radius * 0.3, 0);
  ctx.lineTo(radius * 0.82, 0);
  ctx.stroke();
  ctx.fillStyle = '#fff7df';
  ctx.beginPath();
  ctx.arc(radius * 0.78, 0, Math.max(1, radius * 0.045), 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = alpha;

  // 受击闪白：只有重击 / 顿帧级别的高光才会把整枚齿盘刷白。
  if (hitFlash > 0.8) {
    const bodyFlash = Math.min(1, (hitFlash - 0.8) / 0.2);
    ctx.globalAlpha = alpha * bodyFlash;
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = radius * 0.55;
    ctx.beginPath();
    for (let i = 0; i < toothCount * 2; i += 1) {
      const a = (i / (toothCount * 2)) * Math.PI * 2 + 0.12;
      const toothRadius = i % 2 === 0 ? tipRadius : valleyRadius;
      const px = Math.cos(a) * toothRadius;
      const py = Math.sin(a) * toothRadius;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.globalAlpha = alpha;
  }

  ctx.restore();

  if (hitFlash > 0.01) {
    ctx.strokeStyle = '#ffffff';
    ctx.globalAlpha = alpha * Math.min(1, hitFlash);
    ctx.lineWidth = Math.max(2, radius * 0.14);
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = radius * 0.55;
    ctx.beginPath();
    ctx.arc(x, y, radius * 1.02, 0, Math.PI * 2);
    ctx.stroke();
    ctx.shadowBlur = 0;
  }

  if (tier === 'max') {
    ctx.globalAlpha = alpha * 0.55;
    ctx.strokeStyle = '#ff7a70';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(x, y, radius + radius * 0.48 * (0.9 + Math.sin(time * 9) * 0.1), 0, Math.PI * 2);
    ctx.stroke();
  }

  ctx.globalAlpha = 1;
  ctx.restore();
}
