export type GyroId = 'axis' | 'rend' | 'bulwark' | 'ever' | 'comet';
export type GyroPattern = 'axis' | 'blade' | 'ring' | 'spiral' | 'comet';
export type ChargeTier = 'under' | 'red' | 'max';
export type GameMode = 'cpu' | 'pvp';

export interface GyroStats {
  /** 持久力：影响被动转速衰减 */
  persistence: number;
  /** 攻击力：影响撞击伤害与击退 */
  attack: number;
  /** 防御力：影响自身受到的转速损失 */
  defense: number;
  /** 转速：影响移动响应与最高速度 */
  speed: number;
  /** 重量：影响质量、被击退距离与碰撞惯性 */
  weight: number;
}

export interface GyroPalette {
  body: string;
  light: string;
  dark: string;
  accent: string;
  glow: string;
}

export interface GyroType {
  id: GyroId;
  name: string;
  code: string;
  category: string;
  tagline: string;
  description: string;
  stats: GyroStats;
  colors: GyroPalette;
  pattern: GyroPattern;
  radiusScale: number;
}

export interface Vec2 {
  x: number;
  y: number;
}

