export function getTier(charge: number): ChargeTier {
  if (charge >= CONFIG.charge.max) return 'max';
  if (charge >= CONFIG.charge.red) return 'red';
  return 'under';
}

export function getLaunchPower(charge: number): number {
  if (charge >= CONFIG.charge.max) return CONFIG.launch.maxPower;
  if (charge >= CONFIG.charge.red) {
    const t = (charge - CONFIG.charge.red) / (CONFIG.charge.max - CONFIG.charge.red);
    return CONFIG.launch.redBase + t * CONFIG.launch.redGain;
  }
  const t = charge / CONFIG.charge.red;
  return CONFIG.launch.underBase + t * CONFIG.launch.underGain;
}

export function getMass(type: GyroType): number {
  return CONFIG.physics.massBase + type.stats.weight * CONFIG.physics.massPerWeight;
}

export function getSpeedFactor(type: GyroType): number {
  return CONFIG.physics.speedFactorBase + type.stats.speed * CONFIG.physics.speedFactorPerPoint;
}

export function getSpinDrain(type: GyroType): number {
  return (
    CONFIG.physics.passiveDrainBase +
    (6 - type.stats.persistence) * CONFIG.physics.passiveDrainPerMissing
  );
}

export function getMaxRpm(type: GyroType): number {
  return Math.round(3600 + type.stats.speed * 410 + type.stats.persistence * 95);
}

export function getSpinnerRadius(arenaRadius: number): number {
  return Math.max(
    CONFIG.spinner.minRadius,
    Math.min(CONFIG.spinner.maxRadius, arenaRadius * CONFIG.spinner.radiusRatio),
  );
}

export function getSpawnDistance(arenaRadius: number): number {
  return arenaRadius * CONFIG.arena.spawnRatio;
}

export function getAimDirection(side: 1 | 2, aimOffset: number): Vec2 {
  return {
    x: (side === 1 ? 1 : -1) * Math.cos(aimOffset),
    y: Math.sin(aimOffset),
  };
}

export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

export function lerp(from: number, to: number, t: number): number {
  return from + (to - from) * t;
}

export function randomBetween(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function tierLabel(tier: ChargeTier): string {
  if (tier === 'max') return 'MAX';
  if (tier === 'red') return 'RED';
  return '未满';
}
