import {
  CONFIG,
  getAimDirection,
  getLaunchPower,
  getSpinDrain,
  getSpeedFactor,
  getTier,
  type Vec2,
} from './data';
import type { Spinner } from './spinner';

export interface MoveInput {
  x: number;
  y: number;
}

export interface BoundaryEvent {
  kind: 'bounce' | 'out';
  speed: number;
  normal: Vec2;
  maxPenalty: boolean;
  spinLoss: number;
}

export interface CollisionEvent {
  impact: number;
  point: Vec2;
  normal: Vec2;
  damageA: number;
  damageB: number;
  bonusA: number;
  bonusB: number;
  /**
   * A / B 发射瞬间是否处于 MAX 满力。
   * 直接来自 Spinner.wasMaxHit，而不是碰撞时的实时蓄力档位；
   * warmup 期间也保留该标记，确保满力首撞不会被热身阶段吞掉。
   */
  maxA: boolean;
  maxB: boolean;
  /** 本次碰撞中 A / B 的主动冲刺力度（0 表示未冲刺） */
  dashA: number;
  dashB: number;
  /** 本次碰撞打断了 A / B 的冲刺蓄力 */
  brokenA: boolean;
  brokenB: boolean;
  heavy: boolean;
  warmup: boolean;
}

export function launchSpinner(spinner: Spinner, arenaRadius: number): void {
  const power = getLaunchPower(spinner.charge);
  const direction = getAimDirection(spinner.side, spinner.aimOffset);
  const speed = arenaRadius * CONFIG.launch.speedRatio * power;
  spinner.vel.x = direction.x * speed;
  spinner.vel.y = direction.y * speed;
  spinner.launched = true;
  spinner.tier = getTier(spinner.charge);
  // 在发射瞬间冻结 MAX 判定：后续蓄力清零、实时 tier 变化都不再影响本次撞击。
  spinner.wasMaxHit = spinner.tier === 'max';
  spinner.dashWasMaxHit = false;
  spinner.launchSpinBoost = CONFIG.launch.visualSpinBase + power * CONFIG.launch.visualSpinGain;
}

export function stepMovement(
  spinner: Spinner,
  input: MoveInput,
  dt: number,
  arenaRadius: number,
): void {
  if (!spinner.launched || spinner.out) return;

  // 先扣回上一帧的微震位移：抖动只做原地晃动，绝不累积成真实位移。
  spinner.pos.x -= spinner.idleWobble.x;
  spinner.pos.y -= spinner.idleWobble.y;
  spinner.idleWobble.x = 0;
  spinner.idleWobble.y = 0;

  const speedFactor = getSpeedFactor(spinner.type);
  // 冲刺前摇会牺牲机动性：加速度下降，并且速度被压在较低上限。
  const chargeMoveScale = spinner.dashCharging ? CONFIG.dash.chargeMoveScale : 1;
  const chargeSpeedCap = spinner.dashCharging
    ? arenaRadius * CONFIG.dash.chargeMaxSpeedRatio
    : Number.POSITIVE_INFINITY;
  const length = Math.hypot(input.x, input.y);
  const idle = length <= 0.001;
  if (!idle) {
    const accel =
      arenaRadius * CONFIG.physics.moveAccelRatio * speedFactor * chargeMoveScale;
    spinner.vel.x += (input.x / length) * accel * dt;
    spinner.vel.y += (input.y / length) * accel * dt;
    // 记录“刚刚还在主动走位”：松手后的一小段时间里保留更弱的摩擦。
    spinner.coastTimer = CONFIG.physics.idleCoastDuration;
  } else {
    spinner.coastTimer = Math.max(0, spinner.coastTimer - dt);
  }

  // 统一的桌面摩擦：桌边不再额外加速外漂或降低抓地力。
  // 仅在刚松开走位、余速仍在滑行时减弱摩擦，让陀螺滑一小段而不是瞬间钉住；
  // 发射与撞击击退不经过这段逻辑，手感与平衡保持原样。
  const coasting = idle && spinner.coastTimer > 0;
  const friction =
    CONFIG.physics.friction * (coasting ? CONFIG.physics.idleFrictionScale : 1);
  const damping = Math.exp(-friction * dt);
  spinner.vel.x *= damping;
  spinner.vel.y *= damping;

  const absoluteSpeed = Math.hypot(spinner.vel.x, spinner.vel.y);
  const maxSpeed = Math.min(
    arenaRadius * CONFIG.physics.maxSpeedRatio,
    chargeSpeedCap,
  );
  if (absoluteSpeed > maxSpeed) {
    spinner.vel.x = (spinner.vel.x / absoluteSpeed) * maxSpeed;
    spinner.vel.y = (spinner.vel.y / absoluteSpeed) * maxSpeed;
  }

  spinner.pos.x += spinner.vel.x * dt;
  spinner.pos.y += spinner.vel.y * dt;

  // 转子微震：仅在无走位输入时叠加。幅度为亚像素级，且下一帧会被扣回，
  // 因此只提供“高速旋转中的原地震颤”，不会改变走位精度或碰撞判定的有效半径。
  if (idle) {
    const amplitude =
      arenaRadius *
      CONFIG.physics.idleWobbleRatio *
      (0.45 + spinner.spinRatio * 0.55);
    spinner.idlePhase += dt * CONFIG.physics.idleWobbleSpeed;
    const phase = spinner.idlePhase;
    // 双轴使用不成整数比的频率，再叠一点高频噪声，接近布朗运动的细碎抖动。
    const wobbleX =
      Math.sin(phase) * amplitude +
      Math.sin(phase * 2.37 + 1.1) * amplitude * 0.45 +
      (Math.random() - 0.5) * amplitude * 0.4;
    const wobbleY =
      Math.cos(phase * 1.73 + 0.6) * amplitude +
      Math.cos(phase * 3.11) * amplitude * 0.45 +
      (Math.random() - 0.5) * amplitude * 0.4;
    spinner.pos.x += wobbleX;
    spinner.pos.y += wobbleY;
    spinner.idleWobble.x = wobbleX;
    spinner.idleWobble.y = wobbleY;
  }
}

export function updateSpin(spinner: Spinner, dt: number): void {
  if (!spinner.launched || spinner.out) return;
  spinner.spin = Math.max(
    0,
    spinner.spin - getSpinDrain(spinner.type) * dt,
  );
}


export function resolveBoundary(
  spinner: Spinner,
  arenaRadius: number,
): BoundaryEvent | null {
  if (!spinner.launched || spinner.out) return null;
  const distance = Math.hypot(spinner.pos.x, spinner.pos.y);
  if (distance < 0.001) return null;

  const nx = spinner.pos.x / distance;
  const ny = spinner.pos.y / distance;

  if (distance > arenaRadius) {
    spinner.out = true;
    spinner.outReason = 'ring';
    // 出界即视为血条清零，避免“已死亡但血条仍有剩余”的视觉脱节。
    spinner.spin = 0;
    return {
      kind: 'out',
      speed: Math.hypot(spinner.vel.x, spinner.vel.y),
      normal: { x: nx, y: ny },
      maxPenalty: false,
      spinLoss: 0,
    };
  }

  const boundary = arenaRadius - spinner.radius;
  if (distance <= boundary) return null;

  const outwardSpeed = spinner.vel.x * nx + spinner.vel.y * ny;
  const canBreakThrough =
    outwardSpeed > arenaRadius * CONFIG.physics.outSpeedRatio &&
    spinner.spinRatio > 0.28;

  if (canBreakThrough) {
    // 高速外向冲撞允许穿透桌边，下一帧越过桌面半径即判出界。
    return null;
  }

  spinner.pos.x = nx * boundary;
  spinner.pos.y = ny * boundary;

  const beforeSpeed = Math.hypot(spinner.vel.x, spinner.vel.y);
  if (outwardSpeed > 0) {
    spinner.vel.x -= (1 + CONFIG.physics.wallBounce) * outwardSpeed * nx;
    spinner.vel.y -= (1 + CONFIG.physics.wallBounce) * outwardSpeed * ny;
  }
  spinner.vel.x *= CONFIG.physics.wallSpeedLoss;
  spinner.vel.y *= CONFIG.physics.wallSpeedLoss;
  spinner.spin = Math.max(0, spinner.spin - CONFIG.physics.wallSpinLoss);
  spinner.hitFlash = Math.max(spinner.hitFlash, 0.32);

  let maxPenalty = false;
  if (spinner.tier === 'max' && !spinner.hasHit && !spinner.maxWallPenaltyUsed) {
    spinner.vel.x *= CONFIG.physics.maxWallSpeedFactor;
    spinner.vel.y *= CONFIG.physics.maxWallSpeedFactor;
    spinner.spin = Math.max(0, spinner.spin - CONFIG.physics.maxWallSpinLoss);
    spinner.maxWallPenaltyUsed = true;
    maxPenalty = true;
  }

  return {
    kind: 'bounce',
    speed: Math.max(beforeSpeed, Math.hypot(spinner.vel.x, spinner.vel.y)),
    normal: { x: nx, y: ny },
    maxPenalty,
    spinLoss: CONFIG.physics.wallSpinLoss,
  };
}

/**
 * 手写圆形碰撞 + 冲量公式，不引入物理引擎。
 * 碰撞点、法线、转损、击退与蓄力额外伤害都在这一个函数内完成。
 */
export function resolveCollision(
  a: Spinner,
  b: Spinner,
  arenaRadius: number,
  warmup: boolean,
): CollisionEvent | null {
  if (!a.launched || !b.launched || a.out || b.out) return null;

  // 碰撞判定使用“扣掉转子微震后的真实位置”，保证原地抖动绝不改变接触时机与有效半径。
  const ax = a.pos.x - a.idleWobble.x;
  const ay = a.pos.y - a.idleWobble.y;
  const bx = b.pos.x - b.idleWobble.x;
  const by = b.pos.y - b.idleWobble.y;
  const dx = bx - ax;
  const dy = by - ay;
  const minDistance = a.radius + b.radius;
  const distanceSq = dx * dx + dy * dy;
  if (distanceSq >= minDistance * minDistance) return null;

  const distance = Math.sqrt(distanceSq) || 0.0001;
  const nx = dx / distance;
  const ny = dy / distance;

  // MAX 判定读取发射 / 满力冲刺瞬间冻结的标记，与碰撞时的实时 tier / 蓄力状态无关。
  const maxA = a.wasMaxHit || a.dashWasMaxHit;
  const maxB = b.wasMaxHit || b.dashWasMaxHit;

  // 冲刺判定必须基于碰撞前的速度；冲量结算后速度方向会改变。
  const dashA =
    a.dashActive > 0 && a.vel.x * nx + a.vel.y * ny > arenaRadius * 0.35
      ? a.dashPower
      : 0;
  const dashB =
    b.dashActive > 0 && -(b.vel.x * nx + b.vel.y * ny) > arenaRadius * 0.35
      ? b.dashPower
      : 0;
  const brokenA = a.dashCharging;
  const brokenB = b.dashCharging;

  // 分离：按质量反比推开，防止高速接触时粘在一起。
  const overlap = minDistance - distance + 0.25;
  const inverseA = 1 / a.mass;
  const inverseB = 1 / b.mass;
  const inverseSum = inverseA + inverseB;
  a.pos.x -= nx * overlap * (inverseA / inverseSum);
  a.pos.y -= ny * overlap * (inverseA / inverseSum);
  b.pos.x += nx * overlap * (inverseB / inverseSum);
  b.pos.y += ny * overlap * (inverseB / inverseSum);

  const rvx = b.vel.x - a.vel.x;
  const rvy = b.vel.y - a.vel.y;
  const velocityAlongNormal = rvx * nx + rvy * ny;
  const impact = Math.max(0, -velocityAlongNormal);
  const point = {
    x: a.pos.x + nx * (a.radius - overlap * 0.35),
    y: a.pos.y + ny * (a.radius - overlap * 0.35),
  };

  if (velocityAlongNormal < 0) {
    const restitution = warmup
      ? 0.22
      : CONFIG.physics.collisionRestitution;
    const impulseScale = warmup ? CONFIG.physics.warmupImpulseScale : 1;
    const impulse =
      (-(1 + restitution) * velocityAlongNormal * impulseScale) / inverseSum;
    a.vel.x -= impulse * inverseA * nx;
    a.vel.y -= impulse * inverseA * ny;
    b.vel.x += impulse * inverseB * nx;
    b.vel.y += impulse * inverseB * ny;

    // 切向速度轻微衰减，让擦碰有金属摩擦感。
    const tx = -ny;
    const ty = nx;
    const tangentVelocity = rvx * tx + rvy * ty;
    const tangentImpulse =
      (-tangentVelocity * CONFIG.physics.tangentialFriction) / inverseSum;
    a.vel.x -= tangentImpulse * inverseA * tx;
    a.vel.y -= tangentImpulse * inverseA * ty;
    b.vel.x += tangentImpulse * inverseB * tx;
    b.vel.y += tangentImpulse * inverseB * ty;
  }

  // 攻击力提供额外击退；重量越大越难被推开。
  if (!warmup && impact > 0) {
    const impactNorm = impact / Math.max(1, arenaRadius * 1.4);
    const pushA =
      CONFIG.damage.extraKnockbackRatio *
      impactNorm *
      (a.type.stats.attack + 2) *
      (1 / Math.max(0.7, b.mass));
    const pushB =
      CONFIG.damage.extraKnockbackRatio *
      impactNorm *
      (b.type.stats.attack + 2) *
      (1 / Math.max(0.7, a.mass));
    a.vel.x -= nx * pushB * 22;
    a.vel.y -= ny * pushB * 22;
    b.vel.x += nx * pushA * 22;
    b.vel.y += ny * pushA * 22;
  }

  // 低速接触时补一个明确的分离冲量：否则双方会以相同速度贴在一起，
  // 被走位输入一路推着走，形成长时间的“黏连推挤”。
  if (impact < arenaRadius * 1.1) {
    const unstick = arenaRadius * CONFIG.physics.contactUnstickRatio;
    a.vel.x -= nx * unstick * (inverseA / inverseSum);
    a.vel.y -= ny * unstick * (inverseA / inverseSum);
    b.vel.x += nx * unstick * (inverseB / inverseSum);
    b.vel.y += ny * unstick * (inverseB / inverseSum);
  }

  if (impact < CONFIG.damage.minImpactForHit) {
    return null;
  }

  // 首次“真实”有效碰撞才消耗发射 MAX：轻擦、粘连和撞墙都不会提前吞掉 MAX HIT。
  // 热身期只显示文字、不消耗，保证热身结束后的首次 MAX 撞击（可能同时破招）仍能完整触发。
  if (!warmup) {
    if (a.wasMaxHit) a.wasMaxHit = false;
    if (b.wasMaxHit) b.wasMaxHit = false;
  }
  // 冲刺 MAX 是一次性主动攻击：无论是否处于热身期，有效命中后立即消耗，
  // 这样下一次蓄满力的冲刺仍能重新触发 MAX HIT。
  if (a.dashWasMaxHit) a.dashWasMaxHit = false;
  if (b.dashWasMaxHit) b.dashWasMaxHit = false;

  const impactNorm = impact / Math.max(1, arenaRadius * 1.4);
  const randomA = CONFIG.damage.randomMin + Math.random() * (CONFIG.damage.randomMax - CONFIG.damage.randomMin);
  const randomB = CONFIG.damage.randomMin + Math.random() * (CONFIG.damage.randomMax - CONFIG.damage.randomMin);
  const warmupScale = warmup ? CONFIG.physics.warmupDamageScale : 1;

  const attackA =
    CONFIG.damage.attackBase + a.type.stats.attack * CONFIG.damage.attackPerPoint;
  const attackB =
    CONFIG.damage.attackBase + b.type.stats.attack * CONFIG.damage.attackPerPoint;
  const defenseAFactor = 1 / (
    CONFIG.damage.defenseBase + a.type.stats.defense * CONFIG.damage.defensePerPoint
  );
  const defenseBFactor = 1 / (
    CONFIG.damage.defenseBase + b.type.stats.defense * CONFIG.damage.defensePerPoint
  );

  const baseLossToA =
    (CONFIG.damage.impactBase + impactNorm * CONFIG.damage.impactScale) *
    attackB *
    defenseAFactor *
    randomA;
  const baseLossToB =
    (CONFIG.damage.impactBase + impactNorm * CONFIG.damage.impactScale) *
    attackA *
    defenseBFactor *
    randomB;

  let bonusA = 0;
  let bonusB = 0;
  if (!warmup) {
    if (a.tier === 'red' && !a.chargeBonusUsed) {
      bonusA = CONFIG.damage.redBonus;
      a.chargeBonusUsed = true;
    } else if (a.tier === 'max' && !a.chargeBonusUsed) {
      bonusA = CONFIG.damage.maxBonus;
      a.chargeBonusUsed = true;
    }
    if (b.tier === 'red' && !b.chargeBonusUsed) {
      bonusB = CONFIG.damage.redBonus;
      b.chargeBonusUsed = true;
    } else if (b.tier === 'max' && !b.chargeBonusUsed) {
      bonusB = CONFIG.damage.maxBonus;
      b.chargeBonusUsed = true;
    }
    a.hasHit = true;
    b.hasHit = true;
    a.hitCount += 1;
    b.hitCount += 1;
  }

  // 蓄力加成属于攻击方：A 的加成打 B，B 的加成打 A。
  let damageA = baseLossToA * warmupScale + bonusB;
  let damageB = baseLossToB * warmupScale + bonusA;

  // 主动冲刺命中：大幅放大对防守方的伤害，并追加固定破防值。
  if (dashB > 0) {
    damageA *= 1 + dashB * CONFIG.dash.damageMultiplier;
    damageA += dashB * CONFIG.dash.damageFlat;
  }
  if (dashA > 0) {
    damageB *= 1 + dashA * CONFIG.dash.damageMultiplier;
    damageB += dashA * CONFIG.dash.damageFlat;
  }

  // 冲刺方撞上目标时自身更稳定，避免主动进攻反而先碎。
  if (dashA > 0) damageA *= CONFIG.dash.attackerDamageScale;
  if (dashB > 0) damageB *= CONFIG.dash.attackerDamageScale;

  // 破招：蓄力时被撞，蓄力清空且本次受伤大幅增加。
  if (brokenA) {
    damageA *= CONFIG.dash.breakDamageMultiplier;
    a.dashCharging = false;
    a.dashCharge = 0;
    a.dashInterrupted = true;
    a.dashBreakFlash = 1;
    // 强制封锁：1.5 秒内完全无法再次蓄力，只能走位。
    a.dashLockout = CONFIG.dash.breakCooldown;
    a.sparkTimer = 0;
  }
  if (brokenB) {
    damageB *= CONFIG.dash.breakDamageMultiplier;
    b.dashCharging = false;
    b.dashCharge = 0;
    b.dashInterrupted = true;
    b.dashBreakFlash = 1;
    b.dashLockout = CONFIG.dash.breakCooldown;
    b.sparkTimer = 0;
  }

  // 一次冲刺只强化第一次有效碰撞。
  if (dashA > 0) a.dashActive = 0;
  if (dashB > 0) b.dashActive = 0;

  damageA = Math.max(0, damageA);
  damageB = Math.max(0, damageB);
  a.spin = Math.max(0, a.spin - damageA);
  b.spin = Math.max(0, b.spin - damageB);
  a.hitFlash = Math.max(a.hitFlash, bonusB > 0 ? 1 : 0.55);
  b.hitFlash = Math.max(b.hitFlash, bonusA > 0 ? 1 : 0.55);

  return {
    impact,
    point,
    normal: { x: nx, y: ny },
    damageA,
    damageB,
    bonusA,
    bonusB,
    maxA,
    maxB,
    dashA,
    dashB,
    brokenA,
    brokenB,
    heavy:
      damageA + damageB > 7 ||
      dashA > 0 ||
      dashB > 0 ||
      impact > arenaRadius * 1.65,
    warmup,
  };
}

export function checkStopped(spinner: Spinner): boolean {
  if (!spinner.launched || spinner.out) return false;
  if (spinner.spin <= CONFIG.physics.stopSpin) {
    spinner.spin = 0;
    spinner.out = true;
    spinner.outReason = 'stop';
    return true;
  }
  return false;
}
