import {
  CONFIG,
  GYRO_TYPES,
  SIDE_COLORS,
  STAT_KEYS,
  STAT_LABELS,
  type ChargeTier,
  type GameMode,
  type GyroType,
} from './data';
import { drawGyro } from './spinner';

export interface UIHandlers {
  onMode: (mode: GameMode) => void;
  onBackToMenu: () => void;
  onCard: (index: number) => void;
  onConfirm: () => void;
  onRematch: () => void;
  onSwap: (side: 1 | 2) => void;
  onToggleSfx: () => void;
  onToggleMusic: () => void;
}

export interface SelectionView {
  mode: GameMode;
  p1Index: number;
  p2Index: number;
  active: 1 | 2;
  p1Locked: boolean;
  p2Locked: boolean;
  cpuThinking: boolean;
  /** 结算页“更换陀螺”流程：只更换这一方。 */
  swapSide?: 1 | 2;
}

export interface FighterHudView {
  name: string;
  code: string;
  category: string;
  spin: number;
  rpm: number;
  charge: number;
  tier: ChargeTier;
  locked: boolean;
  dashCharge: number;
  dashCooldown: number;
  dashCharging: boolean;
  /** 破招后的强制蓄力封锁剩余时间（秒）。 */
  dashLockout: number;
}

export interface BattleView {
  p1: FighterHudView;
  p2: FighterHudView;
  phaseLabel: string;
  phaseMode:
    | 'intro'
    | 'ready'
    | 'countdown'
    | 'launch'
    | 'combat'
    | 'warmup'
    | 'ending';
  countdownText: string | null;
  countdownLabel: string;
  hint: string;
  mode: GameMode;
  /** 顶部 HUD 的极小状态提示；战场内不再显示任何文字弹窗。 */
  notice: string;
  noticeTone: 'neutral' | 'good' | 'warn' | 'danger';
  /** 剩余对局时间（秒）；非战斗阶段为 null。 */
  timeLeft: number | null;
}

export interface ResultView {
  draw: boolean;
  winnerSide: 1 | 2;
  winnerName: string;
  winnerType: GyroType;
  loserName: string;
  reason: string;
  remainingSpin: number;
  maxRpm: number;
  hits: number;
  duration: number;
  mode: GameMode;
  p1Name: string;
  p2Name: string;
  p1Type: GyroType;
  p2Type: GyroType;
  p1Spin: number;
  p2Spin: number;
}

interface BattleRefs {
  p1Hud: HTMLElement;
  p1SpinFill: HTMLElement;
  p1SpinValue: HTMLElement;
  p1Rpm: HTMLElement;
  p1ChargeFill: HTMLElement;
  p1ChargeTrack: HTMLElement;
  p1Tier: HTMLElement;
  p1Keyline: HTMLElement;
  p2Hud: HTMLElement;
  p2SpinFill: HTMLElement;
  p2SpinValue: HTMLElement;
  p2Rpm: HTMLElement;
  p2ChargeFill: HTMLElement;
  p2ChargeTrack: HTMLElement;
  p2Tier: HTMLElement;
  p2Keyline: HTMLElement;
  phase: HTMLElement;
  roundCode: HTMLElement;
  countdown: HTMLElement;
  countdownValue: HTMLElement;
  countdownLabelEl: HTMLElement;
  startPrompt: HTMLElement;
  hint: HTMLElement;
  notice: HTMLElement;
}

