import './style.css';
import { Game } from './game';

const canvas = document.querySelector<HTMLCanvasElement>('#arena');
const uiRoot = document.querySelector<HTMLElement>('#ui-root');
const utility = document.querySelector<HTMLElement>('#utility-bar');

if (!canvas || !uiRoot || !utility) {
  throw new Error('Game shell is missing required DOM nodes.');
}

const game = new Game(canvas, uiRoot, utility);

if (import.meta.env.DEV) {
  (window as unknown as { __GYRO_DUEL__: Game }).__GYRO_DUEL__ = game;
}
